      <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-xl shadow-slate-200/30 space-y-4">
        <div className="flex flex-wrap items-center gap-4">
          <div className="flex-1 min-w-[250px] relative">
            <input 
              type="text" 
              placeholder="ابحث باسم المريض أو الوقت..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pr-12 pl-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
            />
            <svg className="w-5 h-5 absolute right-4 top-3.5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
          </div>

          <div className="flex items-center gap-3">
             <button 
               onClick={() => setShowAllFuture(!showAllFuture)}
               className={`px-5 py-3 rounded-2xl text-xs font-black transition-all flex items-center gap-2 border ${
                 showAllFuture ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white text-slate-500 border-slate-200 hover:border-indigo-500'
               }`}
             >
               <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
               {showAllFuture ? 'عرض كافة القادم' : 'تحديد يوم معين'}
             </button>

             {!showAllFuture && (
               <input 
                 type="date" 
                 value={dateFilter}
                 onChange={(e) => setDateFilter(e.target.value)}
                 className="bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
               />
             )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4">
        {isLoading ? (
          <div className="p-20 flex flex-col items-center justify-center gap-4">
             <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
             <p className="text-slate-400 font-black">جاري مزامنة المواعيد...</p>
          </div>
        ) : filteredAppointments.length > 0 ? (
          filteredAppointments.map((app) => (
            <div key={app.id} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-xl hover:border-indigo-100 transition-all flex flex-col md:flex-row md:items-center justify-between gap-6 group">
              <div className="flex items-center gap-5">
                <div className="w-16 h-16 rounded-2xl bg-indigo-50 flex flex-col items-center justify-center border border-indigo-100 shrink-0 shadow-inner group-hover:bg-indigo-600 transition-colors">
                  <span className="text-indigo-600 font-black text-xs group-hover:text-white">{new Date(app.appointment_date).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}</span>
                  {showAllFuture && (
                    <span className="text-[8px] font-bold text-indigo-400 uppercase mt-1 group-hover:text-indigo-200">
                      {new Date(app.appointment_date).toLocaleDateString('ar-EG', { day: 'numeric', month: 'short' })}
                    </span>
                  )}
                </div>
                <div>
                  <h3 className="text-lg font-black text-slate-800 group-hover:text-indigo-600 transition-colors">{app.patient_name}</h3>
                  <p className="text-xs text-slate-400 font-bold mt-1">{app.notes || 'لا توجد ملاحظات'}</p>
                </div>
              </div>

              <div className="flex items-center gap-4">
                <select 
                  value={app.status}
                  onChange={(e) => updateStatus(app.id, e.target.value as AppointmentStatus)}
                  className={`text-[10px] font-black px-4 py-2 rounded-xl border-2 outline-none cursor-pointer ${
                    app.status === AppointmentStatus.PENDING ? 'bg-amber-50 text-amber-600 border-amber-100' :
                    app.status === AppointmentStatus.CONFIRMED ? 'bg-indigo-50 text-indigo-600 border-indigo-100' :
                    app.status === AppointmentStatus.COMPLETED ? 'bg-emerald-50 text-emerald-600 border-emerald-100' :
                    'bg-rose-50 text-rose-600 border-rose-100'
                  }`}
                >
                  <option value={AppointmentStatus.PENDING}>قيد الانتظار</option>
                  <option value={AppointmentStatus.CONFIRMED}>مؤكد</option>
                  <option value={AppointmentStatus.COMPLETED}>مكتمل</option>
                  <option value={AppointmentStatus.CANCELLED}>ملغى</option>
                </select>
              </div>
            </div>
          ))
        ) : (
          <div className="p-24 text-center bg-white rounded-[2.5rem] border-2 border-dashed border-slate-100">
            <p className="text-slate-400 font-bold">لا توجد مواعيد حالية.</p>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] p-8 lg:p-10 max-w-lg w-full shadow-2xl animate-in zoom-in-95 text-right overflow-y-auto max-h-[90vh]">
            <h2 className="text-3xl font-black text-slate-800 mb-6">حجز موعد جديد</h2>
            <form onSubmit={handleAddAppointment} className="space-y-6">

              <div>
                <label className="block text-xs font-black text-slate-400 mb-2.5 uppercase tracking-widest">المريض المختار</label>

                {selectedPatientName ? (
                  <div className="flex items-center justify-between bg-indigo-50 border border-indigo-100 px-5 py-4 rounded-2xl mb-2 animate-in fade-in slide-in-from-top-2">
                    <span className="text-indigo-700 font-black">{selectedPatientName}</span>
                    <button 
                      type="button" 
                      onClick={() => { setFormData({...formData, patient_id: ''}); setSelectedPatientName(null); }}
                      className="text-indigo-400 hover:text-indigo-600"
                    >
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                  </div>
                ) : (
                  <div className="relative">
                    <input 
                      placeholder="ابحث عن اسم المريض للاختيار..."
                      className="w-full px-5 py-4 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold bg-slate-50"
                      value={searchPatientQuery}
                      onChange={(e) => setSearchPatientQuery(e.target.value)}
                    />
                    {searchPatientQuery && filteredPatientList.length > 0 && (
                      <div className="absolute top-full right-0 left-0 mt-2 bg-white border border-slate-100 rounded-2xl shadow-2xl z-50 overflow-hidden divide-y divide-slate-50">
                        {filteredPatientList.map(p => (
                          <button
                            key={p.id}
                            type="button"
                            onClick={() => handleSelectPatient(p.id, p.name)}
                            className="w-full text-right px-6 py-4 hover:bg-indigo-50 transition-colors font-bold text-slate-700 flex items-center justify-between"
                          >
                            <span>{p.name}</span>
                            <svg className="w-4 h-4 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                          </button>
                        ))}
                      </div>
                    )}
                    {searchPatientQuery && filteredPatientList.length === 0 && (
                      <div className="absolute top-full right-0 left-0 mt-2 bg-white border border-slate-100 rounded-2xl p-4 text-center text-slate-400 text-xs font-bold">
                        لا يوجد مريض بهذا الاسم
                      </div>
                    )}
                  </div>
                )}
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-2.5 uppercase tracking-widest">تاريخ الموعد</label>
                  <input 
                    type="date" 
                    required
                    value={formData.appointment_date}
                    onChange={(e) => setFormData({...formData, appointment_date: e.target.value})}
                    className="w-full px-5 py-4 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold"
                  />
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-2.5 uppercase tracking-widest">توقيت الجلسة</label>
                  <input 
                    type="time" 
                    required
                    value={formData.appointment_time}
                    onChange={(e) => setFormData({...formData, appointment_time: e.target.value})}
                    className="w-full px-5 py-4 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-black text-slate-400 mb-2.5 uppercase tracking-widest">ملاحظات طبية</label>
                <textarea 
                  rows={2}
                  value={formData.notes}
                  placeholder="مثال: فحص دوري، تنظيف..."
                  onChange={(e) => setFormData({...formData, notes: e.target.value})}
                  className="w-full px-5 py-4 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold resize-none"
                />
              </div>

              <div className="pt-4 flex flex-col gap-4">
                <button 
                  type="submit" 
                  disabled={isSubmitting || !formData.patient_id}
                  className={`w-full py-5 rounded-[1.5rem] font-black text-base transition-all shadow-xl flex items-center justify-center gap-3 ${
                    !formData.patient_id ? 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-100'
                  }`}
                >
                  {isSubmitting ? (
                    <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  ) : 'إتمام حجز الجلسة'}
                </button>
                <button 
                  type="button" 
                  onClick={() => setIsModalOpen(false)} 
                  className="w-full text-slate-400 font-black py-2 hover:text-slate-600 transition-colors"
                >
                  إلغاء
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Appointments;

import React, { useState, useEffect } from 'react';
import { User, UserRole, Notification } from './types';
import { ICONS } from './constants';
import { supabase, checkDbConnection } from './services/supabase';
import Dashboard from './components/Dashboard';
import PatientCRM from './components/PatientCRM';
import Inventory from './components/Inventory';
import Accounting from './components/Accounting';
import Login from './components/Login';
import AccountManagement from './components/AccountManagement';
import Appointments from './components/Appointments';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [connectionError, setConnectionError] = useState(false);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const initApp = async () => {
      try {
        const isConnected = await checkDbConnection();
        if (!isConnected) {
          setConnectionError(true);
        }

        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
          setCurrentUser({
            id: session.user.id,
            username: session.user.email || '',
            name: session.user.user_metadata?.name || 'مستخدم العيادة',
            role: (session.user.user_metadata?.role as UserRole) || UserRole.RECEPTIONIST
          });
        }
      } catch (err) {
        console.error("App startup failed:", err);
      } finally {
        setIsAuthLoading(false);
      }
    };

    initApp();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) {
        setCurrentUser({
          id: session.user.id,
          username: session.user.email || '',
          name: session.user.user_metadata?.name || 'مستخدم العيادة',
          role: (session.user.user_metadata?.role as UserRole) || UserRole.RECEPTIONIST
        });
      } else {
        setCurrentUser(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setCurrentUser(null);
  };

  const navigateTo = (tab: string) => {
    setActiveTab(tab);
    setIsMobileMenuOpen(false);
  };

  if (isAuthLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center gap-6 p-4">
        <div className="relative">
          <div className="w-16 h-16 border-4 border-slate-100 rounded-full"></div>
          <div className="absolute top-0 w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
        </div>
        <div className="text-center space-y-2">
          <p className="text-slate-800 font-black text-xl tracking-tight">DentaGlow Pro</p>
          <p className="text-slate-400 text-sm animate-pulse font-medium">جاري المزامنة السحابية...</p>
        </div>
      </div>
    );
  }

  if (connectionError && !currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 text-right">
        <div className="max-w-md w-full bg-white p-8 rounded-[2.5rem] shadow-2xl text-center space-y-4">
          <div className="w-20 h-20 bg-rose-50 text-rose-600 rounded-full flex items-center justify-center mx-auto mb-4 border border-rose-100">
            <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
          </div>
          <h2 className="text-2xl font-black text-slate-800">انقطع الاتصال بالسحاب</h2>
          <p className="text-slate-500 text-sm leading-relaxed font-bold">
            يرجى التأكد من اتصال الإنترنت أو إعدادات قاعدة البيانات.
          </p>
          <button onClick={() => window.location.reload()} className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black hover:bg-indigo-700 shadow-xl shadow-indigo-100 transition-all">إعادة المحاولة</button>
        </div>
      </div>
    );
  }

  if (!currentUser) {
    return <Login onLogin={(user) => setCurrentUser(user)} />;
  }

  const tabs = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: ICONS.Dashboard, roles: [UserRole.ADMIN, UserRole.DOCTOR, UserRole.RECEPTIONIST] },
    { id: 'appointments', label: 'المواعيد', icon: ICONS.Calendar, roles: [UserRole.ADMIN, UserRole.DOCTOR, UserRole.RECEPTIONIST] },
    { id: 'patients', label: 'إدارة المرضى', icon: ICONS.Users, roles: [UserRole.ADMIN, UserRole.DOCTOR, UserRole.RECEPTIONIST] },
    { id: 'inventory', label: 'المخزون', icon: ICONS.Inventory, roles: [UserRole.ADMIN, UserRole.RECEPTIONIST] },
    { id: 'accounting', label: 'المحاسبة', icon: ICONS.Accounting, roles: [UserRole.ADMIN] },
    { id: 'accounts', label: 'الموظفين', icon: ICONS.Shield, roles: [UserRole.ADMIN] },
  ];

  const filteredTabs = tabs.filter(tab => tab.roles.includes(currentUser.role));

  const SidebarContent = () => (
    <>
      <div className="p-6 flex items-center gap-3">
        <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shrink-0 shadow-lg shadow-indigo-200">
          <span className="text-white font-black text-xl">D</span>
        </div>
        <span className="font-black text-slate-800 text-xl tracking-tight">DentaGlow</span>
      </div>

      <nav className="flex-1 px-4 space-y-1.5 mt-4 overflow-y-auto no-scrollbar">
        {filteredTabs.map((tab) => (
          <button
            key={tab.id}
            onClick={() => navigateTo(tab.id)}
            className={`w-full flex items-center gap-3 p-3.5 rounded-2xl transition-all ${
              activeTab === tab.id ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-400 hover:bg-slate-50 hover:text-indigo-600'
            }`}
          >
            <tab.icon className="w-6 h-6 shrink-0" />
            <span className="font-black text-sm">{tab.label}</span>
          </button>
        ))}
      </nav>

      <div className="p-4 border-t border-slate-100">
         <button 
           onClick={handleLogout}
           className="w-full flex items-center gap-3 p-3.5 text-rose-400 hover:bg-rose-50 hover:text-rose-600 rounded-2xl transition-all"
         >
           <ICONS.Logout className="w-6 h-6 shrink-0" />
           <span className="font-black text-sm">تسجيل الخروج</span>
         </button>
      </div>
    </>
  );

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans" dir="rtl">
      {/* Desktop Sidebar */}
      <aside className={`bg-white border-l border-slate-200 transition-all duration-300 ${isSidebarOpen ? 'w-64' : 'w-20'} hidden lg:flex flex-col shrink-0`}>
        <div className="p-6 flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shrink-0">
            <span className="text-white font-black text-xl">D</span>
          </div>
          {isSidebarOpen && <span className="font-black text-slate-800 text-xl tracking-tight">DentaGlow</span>}
        </div>
        <nav className="flex-1 px-4 space-y-2 mt-4 overflow-y-auto no-scrollbar">
          {filteredTabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all ${
                activeTab === tab.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-slate-400 hover:bg-slate-50 hover:text-slate-600'
              }`}
            >
              <tab.icon className="w-6 h-6 shrink-0" />
              {isSidebarOpen && <span className="font-bold text-sm">{tab.label}</span>}
            </button>
          ))}
        </nav>
        <div className="p-4 border-t border-slate-100">
           <button onClick={handleLogout} className="w-full flex items-center gap-3 p-3 text-rose-400 hover:bg-rose-50 rounded-xl transition-all">
             <ICONS.Logout className="w-6 h-6 shrink-0" />
             {isSidebarOpen && <span className="font-bold text-sm">تسجيل الخروج</span>}
           </button>
        </div>
      </aside>

      {/* Mobile Drawer */}
      <div className={`fixed inset-0 z-[200] lg:hidden transition-opacity duration-300 ${isMobileMenuOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsMobileMenuOpen(false)}></div>
        <aside className={`absolute top-0 right-0 h-full w-72 bg-white shadow-2xl transition-transform duration-300 transform flex flex-col ${isMobileMenuOpen ? 'translate-x-0' : 'translate-x-full'}`}>
          <SidebarContent />
        </aside>
      </div>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 lg:px-8 shrink-0">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsMobileMenuOpen(true)} className="lg:hidden p-2 text-slate-500 hover:bg-slate-100 rounded-xl transition-all">
               <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="hidden lg:block text-slate-400 hover:text-slate-600">
               <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
          </div>

          <div className="flex items-center gap-3 lg:gap-4">
            <div className="text-left hidden xs:block">
              <p className="text-[9px] lg:text-[10px] font-black text-slate-400 uppercase leading-none mb-1">{currentUser.role}</p>
              <p className="text-xs lg:text-sm font-black text-slate-800 leading-none">{currentUser.name}</p>
            </div>
            <div className="w-9 h-9 lg:w-10 lg:h-10 rounded-full bg-indigo-50 border-2 border-white shadow-sm flex items-center justify-center font-black text-indigo-600 shrink-0 text-sm">
              {currentUser.name.charAt(0)}
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-6 lg:p-8">
          <div className="max-w-[1600px] mx-auto">
            {activeTab === 'dashboard' && <Dashboard onNavigate={navigateTo} userRole={currentUser.role} />}
            {activeTab === 'appointments' && <Appointments currentUser={currentUser} />}
            {activeTab === 'patients' && <PatientCRM />}
            {activeTab === 'inventory' && <Inventory />}
            {activeTab === 'accounting' && <Accounting />}
            {activeTab === 'accounts' && <AccountManagement />}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

