import React, { useState } from 'react';
import { User, UserRole } from '../types';
import { supabase } from '../services/supabase';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.ADMIN);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const formatAsInternalEmail = (id: string) => {
    return `${id.trim().toLowerCase()}@clinic.id`;
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setIsLoading(true);

    const internalEmail = formatAsInternalEmail(username);

    try {
      if (isSignUp) {
        if (username.includes(' ')) throw new Error('اسم المستخدم لا يجب أن يحتوي على مسافات');

        const { data, error: authError } = await supabase.auth.signUp({
          email: internalEmail,
          password,
          options: {
            data: {
              name: name || 'مستخدم جديد',
              role: role,
              username: username.trim().toLowerCase()
            },
          },
        });

        if (authError) throw authError;

        // إضافة بروفايل في جدول البروفايلات لضمان ظهوره في الإدارة
        await supabase.from('profiles').insert([{
          username: username.trim().toLowerCase(),
          name: name || 'مستخدم جديد',
          role: role,
          password_plain: password
        }]);

        if (data.user && data.session === null) {
          setSuccess('تم إنشاء الحساب! يمكنك الآن تسجيل الدخول.');
          setIsSignUp(false);
        } else if (data.user && data.session) {
          onLogin({
            id: data.user.id,
            username: username.trim().toLowerCase(),
            name: name || 'مستخدم جديد',
            role: role
          });
        }
      } else {
        const { data, error: authError } = await supabase.auth.signInWithPassword({
          email: internalEmail,
          password,
        });

        if (authError) {
          // محاولة ثانية: التحقق من جدول البروفايلات (للحسابات التي أنشأها المدير يدوياً)
          const { data: profile } = await supabase
            .from('profiles')
            .select('*')
            .eq('username', username.trim().toLowerCase())
            .eq('password_plain', password)
            .single();

          if (profile) {
            onLogin({
              id: profile.id,
              username: profile.username,
              name: profile.name,
              role: profile.role as UserRole
            });
            return;
          }

          throw new Error('اسم المستخدم (ID) أو كلمة المرور غير صحيحة.');
        }

        if (data.user) {
          onLogin({
            id: data.user.id,
            username: username.trim().toLowerCase(),
            name: data.user.user_metadata?.name || 'مستخدم العيادة',
            role: (data.user.user_metadata?.role as UserRole) || UserRole.RECEPTIONIST
          });
        }
      }
    } catch (err: any) {
      setError(err.message || 'حدث خطأ ما أثناء المصادقة');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4" dir="rtl">
      <div className="max-w-md w-full bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-100 animate-in fade-in zoom-in duration-500">
        <div className="p-8 bg-indigo-600 text-white text-center relative overflow-hidden">
          <div className="relative z-10">
            <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center mx-auto mb-4 backdrop-blur-md border border-white/30 shadow-xl">
              <span className="text-3xl font-black tracking-tighter">D</span>
            </div>
            <h1 className="text-2xl font-black">بوابة عيادة دنتـا</h1>
            <p className="text-indigo-100 text-sm mt-1 font-medium italic">نظام الدخول الموحد (ID Login)</p>
          </div>
        </div>

        <form onSubmit={handleAuth} className="p-8 space-y-5 text-right">
          <div className="flex bg-slate-100 p-1.5 rounded-2xl mb-2">
            <button type="button" onClick={() => setIsSignUp(false)} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${!isSignUp ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500'}`}>تسجيل الدخول</button>
            <button type="button" onClick={() => setIsSignUp(true)} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${isSignUp ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500'}`}>إنشاء حساب</button>
          </div>

          {error && <div className="bg-rose-50 text-rose-600 p-4 rounded-2xl text-[11px] font-black border border-rose-100">{error}</div>}
          {success && <div className="bg-emerald-50 text-emerald-600 p-4 rounded-2xl text-[11px] font-black border border-emerald-100">{success}</div>}

          {isSignUp && (
            <div className="space-y-4 animate-in slide-in-from-top-2">
              <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="الاسم الوظيفي" className="w-full px-5 py-3.5 rounded-2xl bg-slate-50 border border-slate-200 outline-none font-bold text-right" required />
              <select value={role} onChange={(e) => setRole(e.target.value as UserRole)} className="w-full px-5 py-3.5 rounded-2xl bg-slate-50 border border-slate-200 outline-none font-bold text-right">
                <option value={UserRole.ADMIN}>مدير النظام</option>
                <option value={UserRole.DOCTOR}>طبيب</option>
                <option value={UserRole.RECEPTIONIST}>استقبال</option>
              </select>
            </div>
          )}

          <input type="text" value={username} onChange={(e) => setUsername(e.target.value)} placeholder="اسم المستخدم (ID)" className="w-full px-5 py-3.5 rounded-2xl bg-slate-50 border border-slate-200 outline-none font-black text-right" required dir="ltr" />
          <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="كلمة المرور" className="w-full px-5 py-3.5 rounded-2xl bg-slate-50 border border-slate-200 outline-none font-black text-right" required dir="ltr" />

          <button type="submit" disabled={isLoading} className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black text-sm hover:bg-indigo-700 shadow-xl flex items-center justify-center gap-2 disabled:opacity-50">
            {isLoading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : (isSignUp ? 'تفعيل الحساب' : 'دخول النظام')}
          </button>
          <p className="text-[10px] text-slate-400 text-center font-bold">نظام DentaGlow Pro v2.1.0 • مشفر سحابياً</p>
        </form>
      </div>
    </div>
  );
};

export default Login;

-- تفعيل إضافة توليد المعرفات الفريدة
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 0. جدول البروفايلات (بيانات الموظفين)
CREATE TABLE IF NOT EXISTS profiles (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  username TEXT UNIQUE NOT NULL,
  name TEXT NOT NULL,
  role TEXT CHECK (role IN ('ADMIN', 'DOCTOR', 'RECEPTIONIST')),
  password_plain TEXT, -- حفظ كلمة المرور للتمكين الإداري
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 1. جدول المرضى
CREATE TABLE IF NOT EXISTS patients (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  name TEXT NOT NULL,
  phones TEXT[] NOT NULL,
  address TEXT,
  age INTEGER,
  medical_history TEXT[] DEFAULT '{}',
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2. جدول المواد والخدمات
CREATE TABLE IF NOT EXISTS materials (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  name TEXT NOT NULL,
  type TEXT CHECK (type IN ('SERVICE', 'CONSUMABLE')),
  selling_price DECIMAL(12, 2), 
  cost_price DECIMAL(12, 2) NOT NULL, 
  stock_quantity INTEGER DEFAULT 0,
  order_limit INTEGER DEFAULT 10,
  unit TEXT DEFAULT 'قطعة',
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 3. جدول المواعيد
CREATE TABLE IF NOT EXISTS appointments (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  patient_id UUID REFERENCES patients(id) ON DELETE CASCADE,
  doctor_id UUID, 
  appointment_date TIMESTAMP WITH TIME ZONE NOT NULL,
  status TEXT CHECK (status IN ('PENDING', 'CONFIRMED', 'CANCELLED', 'COMPLETED')) DEFAULT 'PENDING',
  notes TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 4. جدول الفواتير
CREATE TABLE IF NOT EXISTS invoices (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  patient_id UUID REFERENCES patients(id) ON DELETE CASCADE,
  doctor_id UUID,
  doctor_commission_pct DECIMAL(5, 2) DEFAULT 0,
  total_gross_amount DECIMAL(12, 2) NOT NULL, 
  external_fees DECIMAL(12, 2) DEFAULT 0, 
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 5. تفعيل سياسات الأمان والحذف المسبق لتجنب الأخطاء
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE patients ENABLE ROW LEVEL SECURITY;
ALTER TABLE materials ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE appointments ENABLE ROW LEVEL SECURITY;

-- حذف السياسات القديمة إن وجدت
DO $$ 
BEGIN
    DROP POLICY IF EXISTS staff_view_profiles ON profiles;
    DROP POLICY IF EXISTS admin_manage_profiles ON profiles;
    DROP POLICY IF EXISTS staff_all_appointments ON appointments;
    DROP POLICY IF EXISTS admin_full_access_materials ON materials;
    DROP POLICY IF EXISTS staff_view_materials ON materials;
    DROP POLICY IF EXISTS staff_manage_patients ON patients;
    DROP POLICY IF EXISTS admin_accounting_access ON invoices;
EXCEPTION WHEN OTHERS THEN 
    NULL;
END $$;

-- إنشاء السياسات من جديد
CREATE POLICY staff_view_profiles ON profiles FOR SELECT TO authenticated USING (TRUE);
CREATE POLICY admin_manage_profiles ON profiles FOR ALL TO authenticated USING (TRUE); -- السماح للمدير (المسجل حالياً) بالإدارة

CREATE POLICY staff_all_appointments ON appointments FOR ALL TO authenticated USING (TRUE) WITH CHECK (TRUE);
CREATE POLICY admin_full_access_materials ON materials FOR ALL TO authenticated USING (TRUE);
CREATE POLICY staff_view_materials ON materials FOR SELECT TO authenticated USING (TRUE);
CREATE POLICY staff_manage_patients ON patients FOR ALL TO authenticated USING (TRUE) WITH CHECK (TRUE);
CREATE POLICY admin_accounting_access ON invoices FOR ALL TO authenticated USING (TRUE);

import React, { useState, useEffect } from 'react';
import { User, UserRole } from '../types';
import { supabase } from '../services/supabase';

const AccountManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showAddModal, setShowAddModal] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [newUser, setNewUser] = useState({ name: '', username: '', role: UserRole.DOCTOR, password: '' });
  const [error, setError] = useState('');

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) setUsers(data);
    } catch (err: any) {
      console.error("Error fetching users:", err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddUser = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const cleanUsername = newUser.username.trim().toLowerCase().replace(/\s/g, '');

    if (!cleanUsername) {
      setError('يرجى إدخال معرف الموظف');
      return;
    }

    if (newUser.password.length < 6) {
      setError('كلمة المرور يجب أن تكون 6 خانات على الأقل');
      return;
    }

    setIsSubmitting(true);
    try {
      // حفظ الموظف في جدول البروفايلات
      const { data, error: profileError } = await supabase
        .from('profiles')
        .insert([{
          username: cleanUsername,
          name: newUser.name.trim(),
          role: newUser.role,
          password_plain: newUser.password
        }])
        .select();

      if (profileError) {
        if (profileError.message.includes('unique_violation')) {
          throw new Error('هذا المعرف (ID) مستخدم بالفعل لموظف آخر.');
        }
        throw profileError;
      }

      // تحديث الواجهة فوراً بجلب البيانات من السحابة
      await fetchUsers();

      setShowAddModal(false);
      setNewUser({ name: '', username: '', role: UserRole.DOCTOR, password: '' });
      alert(`تم تسجيل الموظف ${newUser.name} بنجاح في قاعدة البيانات.`);
    } catch (err: any) {
      setError(err.message || 'فشل في حفظ البيانات السحابية');
    } finally {
      setIsSubmitting(false);
    }
  };

  const deleteUser = async (id: string, username: string) => {
    if (username === 'admin') return alert('لا يمكن حذف حساب المدير الرئيسي');
    if (confirm(`هل أنت متأكد من حذف حساب @${username} نهائياً؟`)) {
      try {
        const { error } = await supabase
          .from('profiles')
          .delete()
          .eq('id', id);

        if (error) throw error;
        setUsers(users.filter(u => u.id !== id));
      } catch (err: any) {
        alert("خطأ في الحذف: " + err.message);
      }
    }
  };

  return (
    <div className="space-y-8 text-right animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-2xl md:text-3xl font-black text-slate-800 tracking-tight">إدارة الكادر الوظيفي</h1>
          <p className="text-slate-500 font-medium italic text-sm">إدارة المعرفات وكلمات المرور المربوطة بسحابة العيادة.</p>
        </div>
        <button 
          onClick={() => { setError(''); setShowAddModal(true); }}
          className="bg-indigo-600 text-white px-8 py-4 rounded-2xl font-black text-sm hover:bg-indigo-700 shadow-xl shadow-indigo-100 flex items-center gap-2 justify-center transition-all active:scale-95"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z" /></svg>
          تسجيل موظف جديد
        </button>
      </div>

      <div className="bg-white border border-slate-100 rounded-[2.5rem] shadow-2xl shadow-slate-200/40 overflow-hidden">
        {isLoading ? (
          <div className="p-20 flex flex-col items-center justify-center gap-4">
             <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
             <p className="text-slate-400 font-black text-sm">جاري جلب بيانات الكادر...</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-right min-w-[850px]">
              <thead className="bg-slate-50/50 border-b border-slate-100">
                <tr>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">الموظف</th>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">المعرف (ID)</th>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">كلمة المرور</th>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">الصلاحية</th>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-left">الإجراءات</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {users.map(user => (
                  <tr key={user.id} className="hover:bg-indigo-50/30 transition-colors group">
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-2xl bg-indigo-100 text-indigo-600 flex items-center justify-center font-black text-lg border-2 border-white shadow-sm shrink-0">
                          {user.name.charAt(0)}
                        </div>
                        <div className="min-w-0">
                          <p className="font-black text-slate-800 truncate">{user.name}</p>
                          <p className="text-[10px] text-slate-400 font-bold uppercase">كادر العيادة</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6 text-center">
                      <code className="bg-slate-100 px-3 py-1.5 rounded-lg text-xs font-black text-indigo-600" dir="ltr">
                        @{user.username}
                      </code>
                    </td>
                    <td className="px-8 py-6 text-center">
                      <span className="text-xs font-mono text-slate-400">
                        {(user as any).password_plain || '••••••••'}
                      </span>
                    </td>
                    <td className="px-8 py-6 text-center">
                      <span className={`text-[10px] font-black px-3 py-1 rounded-xl border ${
                        user.role === UserRole.ADMIN ? 'bg-purple-50 text-purple-600 border-purple-100' : 
                        user.role === UserRole.DOCTOR ? 'bg-indigo-50 text-indigo-600 border-indigo-100' : 'bg-orange-50 text-orange-600 border-orange-100'
                      }`}>
                        {user.role === UserRole.ADMIN ? 'مدير عام' : user.role === UserRole.DOCTOR ? 'طبيب' : 'موظف استقبال'}
                      </span>
                    </td>
                    <td className="px-8 py-6 text-left">
                      <button 
                        onClick={() => deleteUser(user.id, user.username)}
                        className="text-slate-300 hover:text-rose-500 p-2 rounded-xl hover:bg-rose-50 transition-all md:opacity-0 group-hover:opacity-100"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[250] flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] p-8 lg:p-10 max-w-md w-full shadow-2xl animate-in zoom-in-95 text-right my-8">
            <h2 className="text-2xl lg:text-3xl font-black text-slate-800 mb-2">إعداد حساب موظف</h2>
            <p className="text-slate-400 text-xs font-bold mb-8">سيتم الحفظ مباشرة في قاعدة بيانات Supabase.</p>

            {error && (
              <div className="mb-6 p-4 bg-rose-50 text-rose-600 rounded-2xl text-[11px] font-black border border-rose-100 flex items-center gap-2 animate-shake">
                <svg className="w-4 h-4 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                {error}
              </div>
            )}

            <form onSubmit={handleAddUser} className="space-y-5">
              <div>
                <label className="block text-[10px] font-black text-slate-400 mb-2 mr-1 uppercase tracking-widest">الاسم الكامل للموظف</label>
                <input 
                  type="text"
                  required
                  placeholder="مثال: د. ياسين علي"
                  value={newUser.name}
                  onChange={(e) => setNewUser({...newUser, name: e.target.value})}
                  className="w-full px-5 py-4 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold bg-slate-50 transition-all placeholder:text-slate-300"
                />
              </div>

              <div>
                <label className="block text-[10px] font-black text-slate-400 mb-2 mr-1 uppercase tracking-widest">المعرف الفريد (ID Login)</label>
                <div className="relative">
                  <input 
                    type="text"
                    required
                    dir="ltr"
                    placeholder="yassin_dent"
                    value={newUser.username}
                    onChange={(e) => setNewUser({...newUser, username: e.target.value})}
                    className="w-full px-5 py-4 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-black tracking-tight bg-slate-50 transition-all placeholder:text-slate-300"
