import React, { useState } from 'react';
import { User, UserRole } from '../types';
import { supabase } from '../services/supabase';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.ADMIN);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const formatAsInternalEmail = (id: string) => {
    return `${id.trim().toLowerCase()}@clinic.id`;
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setIsLoading(true);

    const cleanUsername = username.trim().toLowerCase();

    try {
      if (isSignUp) {
        // إنشاء حساب عبر Supabase Auth (للمدراء أو التسجيل الذاتي)
        const { data, error: authError } = await supabase.auth.signUp({
          email: formatAsInternalEmail(cleanUsername),
          password,
          options: {
            data: { name, role, username: cleanUsername },
          },
        });

        if (authError) throw authError;

        // مزامنة البروفايل فوراً
        await supabase.from('profiles').insert([{
          username: cleanUsername,
          name: name || 'مستخدم جديد',
          role,
          password_plain: password
        }]);

        if (data.user && data.session) {
          onLogin({ id: data.user.id, username: cleanUsername, name, role });
        } else {
          setSuccess('تم إنشاء الحساب بنجاح! يرجى تسجيل الدخول.');
          setIsSignUp(false);
        }
      } else {
        // 1. محاولة تسجيل دخول الموظفين (عبر جدول البروفايلات)
        const { data: profile, error: profileErr } = await supabase
          .from('profiles')
          .select('*')
          .eq('username', cleanUsername)
          .eq('password_plain', password)
          .single();

        if (profile) {
          onLogin({
            id: profile.id,
            username: profile.username,
            name: profile.name,
            role: profile.role as UserRole
          });
          return;
        }

        // 2. محاولة تسجيل دخول المدراء (عبر Supabase Auth)
        const { data: authData, error: authError } = await supabase.auth.signInWithPassword({
          email: formatAsInternalEmail(cleanUsername),
          password,
        });

        if (authError) {
          throw new Error('بيانات الدخول غير صحيحة. تأكد من المعرف وكلمة المرور.');
        }

        if (authData.user) {
          onLogin({
            id: authData.user.id,
            username: cleanUsername,
            name: authData.user.user_metadata?.name || 'مستخدم النظام',
            role: (authData.user.user_metadata?.role as UserRole) || UserRole.ADMIN
          });
        }
      }
    } catch (err: any) {
      setError(err.message || 'حدث خطأ غير متوقع');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4" dir="rtl">
      <div className="max-w-md w-full bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-100 animate-in fade-in zoom-in duration-500">
        <div className="p-8 bg-indigo-600 text-white text-center relative overflow-hidden">
          <div className="relative z-10">
            <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center mx-auto mb-4 backdrop-blur-md border border-white/30 shadow-xl">
              <span className="text-3xl font-black tracking-tighter">D</span>
            </div>
            <h1 className="text-2xl font-black">بوابة عيادة دنتـا</h1>
            <p className="text-indigo-100 text-sm mt-1 font-medium italic">نظام الدخول السحابي الموحد</p>
          </div>
        </div>

        <form onSubmit={handleAuth} className="p-8 space-y-5 text-right">
          <div className="flex bg-slate-100 p-1.5 rounded-2xl mb-2">
            <button type="button" onClick={() => setIsSignUp(false)} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${!isSignUp ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500'}`}>تسجيل الدخول</button>
            <button type="button" onClick={() => setIsSignUp(true)} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${isSignUp ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500'}`}>إنشاء حساب مدير</button>
          </div>

          {error && <div className="bg-rose-50 text-rose-600 p-4 rounded-2xl text-[11px] font-black border border-rose-100">{error}</div>}
          {success && <div className="bg-emerald-50 text-emerald-600 p-4 rounded-2xl text-[11px] font-black border border-emerald-100">{success}</div>}

          {isSignUp && (
            <div className="space-y-4 animate-in slide-in-from-top-2">
              <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="الاسم الوظيفي الكامل" className="w-full px-5 py-3.5 rounded-2xl bg-slate-50 border border-slate-200 outline-none font-bold text-right" required />
              <select value={role} onChange={(e) => setRole(e.target.value as UserRole)} className="w-full px-5 py-3.5 rounded-2xl bg-slate-50 border border-slate-200 outline-none font-bold text-right">
                <option value={UserRole.ADMIN}>مدير النظام</option>
                <option value={UserRole.DOCTOR}>طبيب</option>
                <option value={UserRole.RECEPTIONIST}>استقبال</option>
              </select>
            </div>
          )}

          <div className="space-y-1">
            <label className="text-[10px] font-black text-slate-400 mr-2 uppercase">المعرف الخاص (ID)</label>
            <input type="text" value={username} onChange={(e) => setUsername(e.target.value)} placeholder="yassin_dent" className="w-full px-5 py-3.5 rounded-2xl bg-slate-50 border border-slate-200 outline-none font-black text-right" required dir="ltr" />
          </div>

          <div className="space-y-1">
            <label className="text-[10px] font-black text-slate-400 mr-2 uppercase">كلمة المرور</label>
            <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" className="w-full px-5 py-3.5 rounded-2xl bg-slate-50 border border-slate-200 outline-none font-black text-right" required dir="ltr" />
          </div>

          <button type="submit" disabled={isLoading} className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black text-sm hover:bg-indigo-700 shadow-xl flex items-center justify-center gap-2 disabled:opacity-50 transition-all active:scale-[0.98]">
            {isLoading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : (isSignUp ? 'تفعيل الحساب السحابي' : 'دخول النظام')}
          </button>

          <div className="text-center pt-2">
             <p className="text-[9px] text-slate-400 font-bold leading-relaxed">
               تنبيه: للموظفين الجدد، يرجى مراجعة مدير العيادة للحصول على معرف الدخول وكلمة المرور الخاصة بك.
             </p>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Login;

-- تفعيل إضافة توليد المعرفات الفريدة
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 0. جدول البروفايلات (قاعدة بيانات الموظفين الأساسية)
CREATE TABLE IF NOT EXISTS profiles (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  username TEXT UNIQUE NOT NULL,
  name TEXT NOT NULL,
  role TEXT CHECK (role IN ('ADMIN', 'DOCTOR', 'RECEPTIONIST')),
  password_plain TEXT NOT NULL, -- كلمة المرور المستخدمة للدخول المباشر
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 1. جدول المرضى
CREATE TABLE IF NOT EXISTS patients (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  name TEXT NOT NULL,
  phones TEXT[] NOT NULL,
  address TEXT,
  age INTEGER,
  medical_history TEXT[] DEFAULT '{}',
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2. جدول المواد والخدمات
CREATE TABLE IF NOT EXISTS materials (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  name TEXT NOT NULL,
  type TEXT CHECK (type IN ('SERVICE', 'CONSUMABLE')),
  selling_price DECIMAL(12, 2), 
  cost_price DECIMAL(12, 2) NOT NULL, 
  stock_quantity INTEGER DEFAULT 0,
  order_limit INTEGER DEFAULT 10,
  unit TEXT DEFAULT 'قطعة',
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 3. جدول المواعيد
CREATE TABLE IF NOT EXISTS appointments (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  patient_id UUID REFERENCES patients(id) ON DELETE CASCADE,
  doctor_id UUID, 
  appointment_date TIMESTAMP WITH TIME ZONE NOT NULL,
  status TEXT CHECK (status IN ('PENDING', 'CONFIRMED', 'CANCELLED', 'COMPLETED')) DEFAULT 'PENDING',
  notes TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 4. جدول الفواتير
CREATE TABLE IF NOT EXISTS invoices (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  patient_id UUID REFERENCES patients(id) ON DELETE CASCADE,
  doctor_id UUID,
  doctor_commission_pct DECIMAL(5, 2) DEFAULT 0,
  total_gross_amount DECIMAL(12, 2) NOT NULL, 
  external_fees DECIMAL(12, 2) DEFAULT 0, 
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 5. تفعيل وتعطيل RLS (لأغراض التطوير والمزامنة المباشرة للموظفين)
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE patients ENABLE ROW LEVEL SECURITY;
ALTER TABLE materials ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE appointments ENABLE ROW LEVEL SECURITY;

-- السماح لجميع العمليات (للمدير والموظفين الموثقين عبر التطبيق)
-- ملاحظة: في بيئة الإنتاج الحقيقية نستخدم auth.uid()، لكن هنا نستخدم الوصول العام المدار برمجياً
DO $$ 
BEGIN
    DROP POLICY IF EXISTS public_access_profiles ON profiles;
    DROP POLICY IF EXISTS public_access_patients ON patients;
    DROP POLICY IF EXISTS public_access_materials ON materials;
    DROP POLICY IF EXISTS public_access_appointments ON appointments;
    DROP POLICY IF EXISTS public_access_invoices ON invoices;
EXCEPTION WHEN OTHERS THEN NULL;
END $$;

CREATE POLICY public_access_profiles ON profiles FOR ALL USING (TRUE);
CREATE POLICY public_access_patients ON patients FOR ALL USING (TRUE);
CREATE POLICY public_access_materials ON materials FOR ALL USING (TRUE);
CREATE POLICY public_access_appointments ON appointments FOR ALL USING (TRUE);
CREATE POLICY public_access_invoices ON invoices FOR ALL USING (TRUE);

