-- تفعيل إضافة توليد المعرفات الفريدة
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 0. جدول البروفايلات (القاعدة الأساسية للموظفين)
CREATE TABLE IF NOT EXISTS profiles (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  username TEXT UNIQUE NOT NULL,
  name TEXT NOT NULL,
  role TEXT CHECK (role IN ('ADMIN', 'DOCTOR', 'RECEPTIONIST')),
  password_plain TEXT NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- إضافة حساب مدير افتراضي إذا لم يكن موجوداً
-- المستخدم: admin
-- كلمة المرور: admin123
INSERT INTO profiles (username, name, role, password_plain)
SELECT 'admin', 'المدير العام', 'ADMIN', 'admin123'
WHERE NOT EXISTS (SELECT 1 FROM profiles WHERE username = 'admin');

-- 1. باقي الجداول
CREATE TABLE IF NOT EXISTS patients (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  name TEXT NOT NULL,
  phones TEXT[] NOT NULL,
  address TEXT,
  age INTEGER,
  medical_history TEXT[] DEFAULT '{}',
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS materials (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  name TEXT NOT NULL,
  type TEXT CHECK (type IN ('SERVICE', 'CONSUMABLE')),
  selling_price DECIMAL(12, 2), 
  cost_price DECIMAL(12, 2) NOT NULL, 
  stock_quantity INTEGER DEFAULT 0,
  order_limit INTEGER DEFAULT 10,
  unit TEXT DEFAULT 'قطعة',
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS appointments (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  patient_id UUID REFERENCES patients(id) ON DELETE CASCADE,
  doctor_id UUID, 
  appointment_date TIMESTAMP WITH TIME ZONE NOT NULL,
  status TEXT CHECK (status IN ('PENDING', 'CONFIRMED', 'CANCELLED', 'COMPLETED')) DEFAULT 'PENDING',
  notes TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS invoices (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  patient_id UUID REFERENCES patients(id) ON DELETE CASCADE,
  doctor_id UUID,
  doctor_commission_pct DECIMAL(5, 2) DEFAULT 0,
  total_gross_amount DECIMAL(12, 2) NOT NULL, 
  external_fees DECIMAL(12, 2) DEFAULT 0, 
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 5. تفعيل RLS وإعطاء صلاحيات وصول عامة للبروفايلات للتحقق من الدخول
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE patients ENABLE ROW LEVEL SECURITY;
ALTER TABLE materials ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE appointments ENABLE ROW LEVEL SECURITY;

-- حذف السياسات القديمة
DO $$ 
BEGIN
    DROP POLICY IF EXISTS public_access_profiles ON profiles;
    DROP POLICY IF EXISTS public_access_patients ON patients;
    DROP POLICY IF EXISTS public_access_materials ON materials;
    DROP POLICY IF EXISTS public_access_appointments ON appointments;
    DROP POLICY IF EXISTS public_access_invoices ON invoices;
EXCEPTION WHEN OTHERS THEN NULL;
END $$;

-- إنشاء سياسات تسمح بالوصول للمستخدمين غير المسجلين (عبر المفتاح العام) للتحقق من الدخول
CREATE POLICY public_access_profiles ON profiles FOR ALL USING (TRUE);
CREATE POLICY public_access_patients ON patients FOR ALL USING (TRUE);
CREATE POLICY public_access_materials ON materials FOR ALL USING (TRUE);
CREATE POLICY public_access_appointments ON appointments FOR ALL USING (TRUE);
CREATE POLICY public_access_invoices ON invoices FOR ALL USING (TRUE);

import React, { useState } from 'react';
import { User, UserRole } from '../types';
import { supabase } from '../services/supabase';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    const cleanUsername = username.trim().toLowerCase();

    try {
      // التحقق من الاتصال أولاً
      const { error: pingError } = await supabase.from('profiles').select('id').limit(1);
      if (pingError) throw new Error('لا يمكن الاتصال بقاعدة البيانات. تأكد من إعدادات Supabase.');

      // التحقق من بيانات الدخول
      const { data: profile, error: profileErr } = await supabase
        .from('profiles')
        .select('*')
        .eq('username', cleanUsername)
        .eq('password_plain', password)
        .maybeSingle();

      if (profileErr) throw profileErr;

      if (!profile) {
        throw new Error('المعرف أو كلمة المرور غير صحيحة.');
      }

      // نجاح الدخول
      onLogin({
        id: profile.id,
        username: profile.username,
        name: profile.name,
        role: profile.role as UserRole
      });

    } catch (err: any) {
      console.error("Login Error:", err);
      setError(err.message || 'حدث خطأ غير متوقع أثناء الدخول');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4" dir="rtl">
      <div className="max-w-md w-full bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-slate-100 animate-in fade-in zoom-in duration-500">
        <div className="p-10 bg-indigo-600 text-white text-center relative overflow-hidden">
          <div className="relative z-10">
            <div className="w-20 h-20 bg-white/20 rounded-[2rem] flex items-center justify-center mx-auto mb-6 backdrop-blur-md border border-white/30 shadow-2xl">
              <span className="text-4xl font-black tracking-tighter">D</span>
            </div>
            <h1 className="text-3xl font-black mb-2 tracking-tight">عيادة دنتـا جلو</h1>
            <p className="text-indigo-100 text-sm font-bold italic opacity-80">نظام الإدارة السحابي الموحد</p>
          </div>
          <div className="absolute -top-10 -right-10 w-40 h-40 bg-white/10 rounded-full blur-3xl"></div>
        </div>

        <form onSubmit={handleLogin} className="p-10 space-y-6 text-right">
          <div className="text-center mb-4">
            <h2 className="text-slate-800 font-black text-xl">تسجيل الدخول</h2>
            <p className="text-slate-400 text-[10px] font-black mt-1 uppercase tracking-widest">ادخل بياناتك للوصول للعيادة</p>
          </div>

          {error && (
            <div className="bg-rose-50 text-rose-600 p-4 rounded-2xl text-[11px] font-black border border-rose-100 animate-shake flex items-center gap-3">
              <div className="w-8 h-8 bg-rose-100 rounded-full flex items-center justify-center shrink-0">
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              </div>
              {error}
            </div>
          )}

          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-400 mr-2 uppercase tracking-widest">المعرف الوظيفي (ID)</label>
            <div className="relative">
              <input 
                type="text" 
                value={username} 
                onChange={(e) => setUsername(e.target.value)} 
                placeholder="yassin_admin" 
                className="w-full px-6 py-4 rounded-2xl bg-slate-50 border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-black text-right transition-all placeholder:text-slate-300" 
                required 
                dir="ltr" 
              />
              <span className="absolute left-4 top-4 text-slate-300 font-black">@</span>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-400 mr-2 uppercase tracking-widest">كلمة المرور</label>
            <input 
              type="password" 
              value={password} 
              onChange={(e) => setPassword(e.target.value)} 
              placeholder="••••••••" 
              className="w-full px-6 py-4 rounded-2xl bg-slate-50 border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-black text-right transition-all placeholder:text-slate-300" 
              required 
              dir="ltr" 
            />
          </div>

          <button 
            type="submit" 
            disabled={isLoading} 
            className="w-full bg-indigo-600 text-white py-5 rounded-2xl font-black text-sm hover:bg-indigo-700 shadow-xl shadow-indigo-100 flex items-center justify-center gap-2 disabled:opacity-50 transition-all active:scale-[0.98] mt-4"
          >
            {isLoading ? <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : 'دخول النظام'}
          </button>

          <div className="text-center pt-4 border-t border-slate-50">
             <p className="text-[10px] text-slate-300 font-bold leading-relaxed">
               بيانات الدخول الافتراضية للمدير: <span className="text-indigo-400" dir="ltr">admin / admin123</span>
             </p>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
