interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [dbStatus, setDbStatus] = useState<'CHECKING' | 'READY' | 'EMPTY' | 'ERROR'>('CHECKING');

  // تشخيص حالة قاعدة البيانات عند فتح الشاشة
  useEffect(() => {
    const checkDatabase = async () => {
      try {
        const { data, count, error } = await supabase
          .from('profiles')
          .select('*', { count: 'exact', head: true });

        if (error) {
          console.error("DB Diagnostic Error:", error);
          setDbStatus('ERROR');
          return;
        }

        if (count === 0) {
          setDbStatus('EMPTY');
        } else {
          setDbStatus('READY');
        }
      } catch (err) {
        setDbStatus('ERROR');
      }
    };
    checkDatabase();
  }, []);

  const createEmergencyAdmin = async () => {
    setIsLoading(true);
    setError('');
    try {
      const { error: insertError } = await supabase.from('profiles').insert([
        {
          username: 'admin',
          name: 'المدير العام (افتراضي)',
          role: UserRole.ADMIN,
          password_plain: 'admin123'
        }
      ]);

      if (insertError) throw insertError;

      setDbStatus('READY');
