                      className="w-full px-6 py-4 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold bg-slate-50 transition-all placeholder:text-slate-300"
                      value={searchPatientQuery}
                      onChange={(e) => setSearchPatientQuery(e.target.value)}
                    />
                    {searchPatientQuery && filteredPatientList.length > 0 && (
                      <div className="absolute top-full right-0 left-0 mt-2 bg-white border border-slate-100 rounded-2xl shadow-2xl z-50 overflow-hidden divide-y divide-slate-50 max-h-60 overflow-y-auto">
                        {filteredPatientList.map(p => (
                          <button
                            key={p.id}
                            type="button"
                            onClick={() => handleSelectPatient(p.id, p.name)}
                            className="w-full text-right px-6 py-4 hover:bg-indigo-50 transition-colors font-bold text-slate-700 flex items-center justify-between group"
                          >
                            <span>{p.name}</span>
                            <svg className="w-4 h-4 text-indigo-400 opacity-0 group-hover:opacity-100 transition-opacity" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                          </button>
                        ))}
                      </div>
                    )}
                    {searchPatientQuery && filteredPatientList.length === 0 && (
                      <div className="absolute top-full right-0 left-0 mt-2 bg-white border border-slate-100 rounded-2xl p-6 text-center shadow-xl z-50">
                        <p className="text-slate-400 text-xs font-bold mb-3">لا يوجد مريض بهذا الاسم</p>
                        <p className="text-[10px] text-slate-300">يجب تسجيل المريض أولاً في قسم "إدارة المرضى"</p>
                      </div>
                    )}
                    {!searchPatientQuery && patients.length === 0 && (
                      <div className="mt-2 p-4 bg-amber-50 border border-amber-100 rounded-2xl text-[11px] font-bold text-amber-700 text-center">
                        ⚠️ تنبيه: لا يوجد مرضى مسجلون في النظام حالياً.
                      </div>
                    )}
                  </div>
                )}
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-2.5 uppercase tracking-widest">يوم الموعد</label>
                  <input 
                    type="date" 
                    required
                    value={formData.appointment_date}
                    onChange={(e) => setFormData({...formData, appointment_date: e.target.value})}
                    className="w-full px-5 py-4 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold bg-slate-50"
                  />
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-2.5 uppercase tracking-widest">توقيت الساعة</label>
                  <input 
                    type="time" 
                    required
                    value={formData.appointment_time}
                    onChange={(e) => setFormData({...formData, appointment_time: e.target.value})}
                    className="w-full px-5 py-4 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold bg-slate-50"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-black text-slate-400 mb-2.5 uppercase tracking-widest">ملاحظات / سبب الزيارة</label>
                <textarea 
                  rows={2}
                  value={formData.notes}
                  placeholder="مثال: تركيب زيركون، خلع ضرس عقل..."
                  onChange={(e) => setFormData({...formData, notes: e.target.value})}
                  className="w-full px-5 py-4 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold resize-none bg-slate-50 transition-all"
                />
              </div>

              <div className="pt-4 flex flex-col gap-4">
                <button 
                  type="submit" 
                  disabled={isSubmitting || !formData.patient_id}
                  className={`w-full py-5 rounded-[1.5rem] font-black text-base transition-all shadow-xl flex items-center justify-center gap-3 ${
                    !formData.patient_id ? 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-100 active:scale-[0.98]'
                  }`}
                >
                  {isSubmitting ? (
                    <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  ) : 'تأكيد الحجز وحفظه سحابياً'}
                </button>
                <button 
                  type="button" 
                  onClick={() => setIsModalOpen(false)} 
                  className="w-full text-slate-400 font-black py-2 hover:text-slate-600 transition-colors text-sm"
                >
                  إلغاء العملية
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Appointments;

-- 1. التأكد من وجود الإضافات اللازمة
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 2. إنشاء أو تحديث جدول البروفايلات
CREATE TABLE IF NOT EXISTS profiles (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  username TEXT UNIQUE NOT NULL,
  name TEXT NOT NULL,
  role TEXT CHECK (role IN ('ADMIN', 'DOCTOR', 'RECEPTIONIST')),
  password_plain TEXT NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 3. إنشاء أو تحديث جدول المرضى
CREATE TABLE IF NOT EXISTS patients (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  name TEXT NOT NULL,
  phones TEXT[] NOT NULL,
  address TEXT,
  age INTEGER,
  medical_history TEXT[] DEFAULT '{}',
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 4. إصلاح جدول المواعيد وحذف القيود القديمة المتعارضة
-- ملاحظة: نقوم بحذف القيد القديم إذا كان موجوداً لتجنب خطأ "Key is not present in table users"
DO $$ 
BEGIN
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'appointments_doctor_id_fkey') THEN
        ALTER TABLE appointments DROP CONSTRAINT appointments_doctor_id_fkey;
    END IF;
END $$;

CREATE TABLE IF NOT EXISTS appointments (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  patient_id UUID REFERENCES patients(id) ON DELETE CASCADE,
  doctor_id UUID REFERENCES profiles(id) ON DELETE SET NULL, -- الربط بجدول البروفايلات
  appointment_date TIMESTAMP WITH TIME ZONE NOT NULL,
  status TEXT CHECK (status IN ('PENDING', 'CONFIRMED', 'CANCELLED', 'COMPLETED')) DEFAULT 'PENDING',
  notes TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 5. جدول الفواتير والمواد
CREATE TABLE IF NOT EXISTS materials (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  name TEXT NOT NULL,
  type TEXT CHECK (type IN ('SERVICE', 'CONSUMABLE')),
  selling_price DECIMAL(12, 2), 
  cost_price DECIMAL(12, 2) NOT NULL, 
  stock_quantity INTEGER DEFAULT 0,
  order_limit INTEGER DEFAULT 10,
  unit TEXT DEFAULT 'قطعة',
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS invoices (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  patient_id UUID REFERENCES patients(id) ON DELETE CASCADE,
  doctor_id UUID REFERENCES profiles(id) ON DELETE SET NULL,
  doctor_commission_pct DECIMAL(5, 2) DEFAULT 0,
  total_gross_amount DECIMAL(12, 2) NOT NULL, 
  external_fees DECIMAL(12, 2) DEFAULT 0, 
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

