ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE patients ENABLE ROW LEVEL SECURITY;
ALTER TABLE materials ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE appointments ENABLE ROW LEVEL SECURITY;

CREATE POLICY IF NOT EXISTS public_access_profiles ON profiles FOR ALL USING (TRUE);
CREATE POLICY IF NOT EXISTS public_access_patients ON patients FOR ALL USING (TRUE);
CREATE POLICY IF NOT EXISTS public_access_materials ON materials FOR ALL USING (TRUE);
CREATE POLICY IF NOT EXISTS public_access_appointments ON appointments FOR ALL USING (TRUE);
CREATE POLICY IF NOT EXISTS public_access_invoices ON invoices FOR ALL USING (TRUE);

