import React, { useState, useEffect, useMemo } from 'react';
import { Appointment, AppointmentStatus, Patient, User, UserRole } from '../types';
import { supabase } from '../services/supabase';

interface AppointmentsProps {
  currentUser?: User | null;
}

const Appointments: React.FC<AppointmentsProps> = ({ currentUser }) => {
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [patients, setPatients] = useState<Patient[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [dateFilter, setDateFilter] = useState(new Date().toISOString().split('T')[0]);
  const [statusFilter, setStatusFilter] = useState<string>('ALL');
  const [searchQuery, setSearchQuery] = useState('');
  const [showAllFuture, setShowAllFuture] = useState(false);

  const [formData, setFormData] = useState({
    patient_id: '',
    appointment_date: new Date().toISOString().split('T')[0],
    appointment_time: '10:00',
    notes: '',
    status: AppointmentStatus.PENDING
  });

  const [selectedPatientName, setSelectedPatientName] = useState<string | null>(null);
  const [searchPatientQuery, setSearchPatientQuery] = useState('');

  useEffect(() => {
    fetchAppointments();
    fetchPatients();
  }, [dateFilter, showAllFuture]);

  const fetchPatients = async () => {
    try {
      const { data, error } = await supabase.from('patients').select('id, name').order('name');
      if (error) throw error;
      if (data) setPatients(data);
    } catch (err) {
      console.error("Error fetching patients:", err);
    }
  };

  const fetchAppointments = async () => {
    setIsLoading(true);
    try {
      let query = supabase
        .from('appointments')
        .select(`
          *,
          patients ( name )
        `);

      if (showAllFuture) {
        const todayStart = new Date();
        todayStart.setHours(0, 0, 0, 0);
        query = query.gte('appointment_date', todayStart.toISOString());
      } else {
        query = query
          .gte('appointment_date', `${dateFilter}T00:00:00.000Z`)
          .lte('appointment_date', `${dateFilter}T23:59:59.999Z`);
      }

      const { data, error } = await query.order('appointment_date', { ascending: true });
      if (error) throw error;

      const mapped = data?.map(app => ({
        ...app,
        patient_name: app.patients?.name || 'مريض غير معروف'
      })) || [];

      setAppointments(mapped);
    } catch (err) {
      console.error("Error fetching appointments:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const filteredAppointments = useMemo(() => {
    return appointments.filter(app => {
      const matchesStatus = statusFilter === 'ALL' || app.status === statusFilter;
      const patientName = app.patient_name || '';
      const matchesSearch = patientName.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesStatus && matchesSearch;
    });
  }, [appointments, statusFilter, searchQuery]);

  const handleSelectPatient = (id: string, name: string) => {
    setFormData(prev => ({ ...prev, patient_id: id }));
    setSelectedPatientName(name);
    setSearchPatientQuery('');
  };

  const handleAddAppointment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.patient_id) {
      alert("يرجى اختيار مريض أولاً.");
      return;
    }

    setIsSubmitting(true);
    try {
      const combinedDate = new Date(`${formData.appointment_date}T${formData.appointment_time}`);

      // إذا كان المستخدم أدمن أو استقبال، لا نسند doctor_id حالياً لتجنب مشاكل FK حتى يتم اختيار الطبيب يدوياً
      const doctorIdToSave = currentUser?.role === UserRole.DOCTOR ? currentUser.id : null;

      const { error } = await supabase
        .from('appointments')
        .insert([{
          patient_id: formData.patient_id,
          doctor_id: doctorIdToSave,
          appointment_date: combinedDate.toISOString(),
          status: formData.status,
          notes: formData.notes.trim()
        }]);

      if (error) throw error;

      await fetchAppointments();
      setIsModalOpen(false);
      resetForm();
      alert("تم حجز الموعد بنجاح!");

    } catch (err: any) {
      console.error("Insert Error:", err);
      if (err.message.includes('foreign key constraint')) {
        alert("خطأ في قاعدة البيانات: يرجى نسخ وتشغيل كود SQL المحدث في Supabase (SQL Editor) لإصلاح ربط الجداول.");
      } else {
        alert("فشل الحجز: " + err.message);
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  const resetForm = () => {
    setFormData({
      patient_id: '',
      appointment_date: new Date().toISOString().split('T')[0],
      appointment_time: '10:00',
      notes: '',
      status: AppointmentStatus.PENDING
    });
    setSelectedPatientName(null);
    setSearchPatientQuery('');
  };

  const updateStatus = async (id: string, newStatus: AppointmentStatus) => {
    try {
      const { error } = await supabase.from('appointments').update({ status: newStatus }).eq('id', id);
      if (error) throw error;
      fetchAppointments();
    } catch (err: any) {
      alert("خطأ في تحديث الحالة: " + err.message);
    }
  };

  const filteredPatientList = useMemo(() => {
    if (!searchPatientQuery) return [];
    return patients.filter(p => p.name.toLowerCase().includes(searchPatientQuery.toLowerCase())).slice(0, 5);
  }, [patients, searchPatientQuery]);

  return (
    <div className="space-y-6 text-right animate-in fade-in duration-500">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-black text-slate-800">جدول المواعيد</h1>
          <p className="text-slate-500 text-xs">إدارة حجوزات العيادة</p>
        </div>
        <button 
          onClick={() => { resetForm(); setIsModalOpen(true); }}
          className="bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold text-sm shadow-lg hover:bg-indigo-700 transition-all"
        >
          حجز موعد
        </button>
      </div>

      <div className="bg-white p-4 rounded-3xl border border-slate-100 shadow-sm flex flex-wrap gap-4">
        <input 
          type="date" 
          value={dateFilter}
          onChange={(e) => setDateFilter(e.target.value)}
          className="bg-slate-50 border-none rounded-xl px-4 py-2 text-sm font-bold"
        />
        <input 
          type="text" 
          placeholder="بحث سريع..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="bg-slate-50 border-none rounded-xl px-4 py-2 text-sm font-bold flex-1"
        />
      </div>

      <div className="space-y-3">
        {isLoading ? (
          <div className="p-10 text-center text-slate-400 font-bold">جاري التحميل...</div>
        ) : filteredAppointments.length > 0 ? (
          filteredAppointments.map((app) => (
            <div key={app.id} className="bg-white p-4 rounded-2xl border border-slate-50 shadow-sm flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="bg-indigo-50 text-indigo-600 px-3 py-2 rounded-lg font-black text-xs">
                  {new Date(app.appointment_date).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}
                </div>
                <div>
                  <p className="font-black text-slate-800">{app.patient_name}</p>
                  <p className="text-[10px] text-slate-400 font-bold">{app.notes || 'لا ملاحظات'}</p>
                </div>
              </div>
              <select 
                value={app.status}
                onChange={(e) => updateStatus(app.id, e.target.value as AppointmentStatus)}
                className="text-[10px] font-black bg-slate-50 border-none rounded-lg p-2"
              >
                <option value={AppointmentStatus.PENDING}>انتظار</option>
                <option value={AppointmentStatus.CONFIRMED}>مؤكد</option>
                <option value={AppointmentStatus.COMPLETED}>مكتمل</option>
                <option value={AppointmentStatus.CANCELLED}>ملغى</option>
              </select>
            </div>
          ))
        ) : (
          <div className="p-10 text-center text-slate-300 italic">لا توجد مواعيد لهذا التاريخ.</div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 max-w-md w-full shadow-2xl animate-in zoom-in-95 text-right">
            <h2 className="text-xl font-black mb-6">موعد جديد</h2>
            <form onSubmit={handleAddAppointment} className="space-y-4">
              <div className="relative">
                <label className="block text-[10px] font-black text-slate-400 mb-1">المريض</label>
                {selectedPatientName ? (
                  <div className="bg-indigo-50 p-3 rounded-xl flex items-center justify-between">
                    <span className="font-bold text-indigo-700">{selectedPatientName}</span>
                    <button type="button" onClick={() => { setSelectedPatientName(null); setFormData({...formData, patient_id: ''}); }}>×</button>
                  </div>
                ) : (
                  <>
                    <input 
                      placeholder="ابحث عن مريض..."
                      value={searchPatientQuery}
                      onChange={(e) => setSearchPatientQuery(e.target.value)}
                      className="w-full bg-slate-50 border-none rounded-xl p-3 font-bold"
                    />
                    {filteredPatientList.length > 0 && (
                      <div className="absolute w-full mt-1 bg-white border rounded-xl shadow-xl z-10 overflow-hidden">
                        {filteredPatientList.map(p => (
                          <button key={p.id} type="button" onClick={() => handleSelectPatient(p.id, p.name)} className="w-full p-3 text-right hover:bg-indigo-50 font-bold text-sm">
                            {p.name}
                          </button>
                        ))}
                      </div>
                    )}
                  </>
                )}
              </div>
              <div className="grid grid-cols-2 gap-3">
                <input type="date" value={formData.appointment_date} onChange={(e) => setFormData({...formData, appointment_date: e.target.value})} className="bg-slate-50 border-none rounded-xl p-3 font-bold" />
                <input type="time" value={formData.appointment_time} onChange={(e) => setFormData({...formData, appointment_time: e.target.value})} className="bg-slate-50 border-none rounded-xl p-3 font-bold" />
              </div>
              <textarea placeholder="ملاحظات..." value={formData.notes} onChange={(e) => setFormData({...formData, notes: e.target.value})} className="w-full bg-slate-50 border-none rounded-xl p-3 font-bold h-20" />
              <button type="submit" disabled={isSubmitting} className="w-full bg-indigo-600 text-white p-4 rounded-2xl font-black shadow-lg shadow-indigo-100">
                {isSubmitting ? 'جاري الحفظ...' : 'تأكيد الحجز'}
              </button>
              <button type="button" onClick={() => setIsModalOpen(false)} className="w-full text-slate-400 font-bold text-xs py-2">إلغاء</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

