import { Appointment, AppointmentStatus, Patient, User, UserRole } from '../types';
import { supabase } from '../services/supabase';

interface AppointmentsProps {
  currentUser?: User | null;
}

const Appointments: React.FC<AppointmentsProps> = ({ currentUser }) => {
  const [appointments, setAppointments] = useState<(Appointment & { doctor_name?: string, patient_name?: string })[]>([]);
  const [patients, setPatients] = useState<Patient[]>([]);
  const [doctors, setDoctors] = useState<{ id: string, name: string }[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [dateFilter, setDateFilter] = useState(new Date().toISOString().split('T')[0]);
  const [searchQuery, setSearchQuery] = useState('');
  const [viewMode, setViewMode] = useState<'TODAY' | 'FUTURE' | 'ALL'>('TODAY');

  const [formData, setFormData] = useState({
    patient_id: '',
    doctor_id: '',
    appointment_date: new Date().toISOString().split('T')[0],
    appointment_time: '10:00',
    notes: '',
    status: AppointmentStatus.PENDING
  });

  const [selectedPatientName, setSelectedPatientName] = useState<string | null>(null);
  const [searchPatientQuery, setSearchPatientQuery] = useState('');

  useEffect(() => {
    fetchAppointments();
    fetchPatients();
    fetchDoctors();
  }, [dateFilter, viewMode]);

  useEffect(() => {
    if (currentUser?.role === UserRole.DOCTOR && !formData.doctor_id) {
      setFormData(prev => ({ ...prev, doctor_id: currentUser.id }));
    }
  }, [currentUser, isModalOpen]);

  const fetchDoctors = async () => {
    const { data, error } = await supabase
      .from('profiles')
      .select('id, name')
      .eq('role', UserRole.DOCTOR);
    if (!error && data) setDoctors(data);
  };

  const fetchPatients = async () => {
    try {
      const { data, error } = await supabase.from('patients').select('id, name').order('name');
      if (error) throw error;
      if (data) setPatients(data);
    } catch (err) {
      console.error("Error fetching patients:", err);
    }
  };

  const fetchAppointments = async () => {
    setIsLoading(true);
    try {
      // استخدام الربط الصريح profiles!doctor_id لتجنب خطأ العلاقات غير المعروفة
      let query = supabase
        .from('appointments')
        .select(`
          *,
          patients!patient_id ( name ),
          profiles!doctor_id ( name )
        `);

      if (viewMode === 'FUTURE') {
        const todayStart = new Date();
        todayStart.setHours(0, 0, 0, 0);
        query = query.gte('appointment_date', todayStart.toISOString());
      } else if (viewMode === 'TODAY') {
        query = query
          .gte('appointment_date', `${dateFilter}T00:00:00.000Z`)
          .lte('appointment_date', `${dateFilter}T23:59:59.999Z`);
      }

      const { data, error } = await query.order('appointment_date', { ascending: false });

      if (error) {
        // إذا فشل الربط الصريح، نحاول جلب البيانات الخام بدون ربط لضمان ظهور المواعيد على الأقل
        console.warn("Join failed, fetching raw appointments:", error);
        const { data: rawData, error: rawError } = await supabase
          .from('appointments')
          .select('*')
          .order('appointment_date', { ascending: false });

        if (rawError) throw rawError;

        setAppointments(rawData || []);
      } else {
        const mapped = data?.map(app => ({
          ...app,
          patient_name: (app.patients as any)?.name || 'مريض غير معروف',
          doctor_name: (app.profiles as any)?.name || 'طبيب غير محدد'
        })) || [];
        setAppointments(mapped);
      }
