import React, { useState, useEffect, useMemo } from 'react';
import { Appointment, AppointmentStatus, Patient, User, UserRole } from '../types';
import { supabase } from '../services/supabase';

interface AppointmentsProps {
  currentUser?: User | null;
}

const Appointments: React.FC<AppointmentsProps> = ({ currentUser }) => {
  const [appointments, setAppointments] = useState<(Appointment & { doctor_name?: string, patient_name?: string })[]>([]);
  const [patients, setPatients] = useState<Patient[]>([]);
  const [doctors, setDoctors] = useState<{ id: string, name: string }[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [dateFilter, setDateFilter] = useState(new Date().toISOString().split('T')[0]);
  const [searchQuery, setSearchQuery] = useState('');
  const [viewMode, setViewMode] = useState<'TODAY' | 'FUTURE' | 'ALL'>('TODAY');

  // إعدادات الوقت الافتراضية
  const [formData, setFormData] = useState({
    patient_id: '',
    doctor_id: '',
    appointment_date: new Date().toISOString().split('T')[0],
    hour: '10',
    minute: '00',
    period: 'AM',
    notes: '',
    status: AppointmentStatus.PENDING
  });

  const [selectedPatientName, setSelectedPatientName] = useState<string | null>(null);
  const [searchPatientQuery, setSearchPatientQuery] = useState('');

  useEffect(() => {
    const initData = async () => {
      await Promise.all([fetchPatients(), fetchDoctors()]);
      await fetchAppointments();
    };
    initData();
  }, [dateFilter, viewMode]);

  useEffect(() => {
    if (currentUser?.role === UserRole.DOCTOR && !formData.doctor_id) {
      setFormData(prev => ({ ...prev, doctor_id: currentUser.id }));
    }
  }, [currentUser, isModalOpen]);

  const fetchDoctors = async () => {
    const { data, error } = await supabase
      .from('profiles')
      .select('id, name')
      .eq('role', UserRole.DOCTOR);
    if (!error && data) setDoctors(data);
    return data || [];
  };

  const fetchPatients = async () => {
    try {
      const { data, error } = await supabase.from('patients').select('id, name').order('name');
      if (!error && data) setPatients(data);
      return data || [];
    } catch (err) {
      console.error("Error fetching patients:", err);
      return [];
    }
  };

  const fetchAppointments = async () => {
    setIsLoading(true);
    try {
      let query = supabase.from('appointments').select('*');

      if (viewMode === 'FUTURE') {
        const todayStart = new Date();
        todayStart.setHours(0, 0, 0, 0);
        query = query.gte('appointment_date', todayStart.toISOString());
      } else if (viewMode === 'TODAY') {
        query = query
          .gte('appointment_date', `${dateFilter}T00:00:00.000Z`)
          .lte('appointment_date', `${dateFilter}T23:59:59.999Z`);
      }

      const { data: appData, error: appError } = await query.order('appointment_date', { ascending: false });
      if (appError) throw appError;

      const { data: pData } = await supabase.from('patients').select('id, name');
      const { data: dData } = await supabase.from('profiles').select('id, name');

      const pMap = new Map(pData?.map(p => [p.id, p.name]));
      const dMap = new Map(dData?.map(d => [d.id, d.name]));

      const mapped = appData?.map(app => ({
        ...app,
        patient_name: pMap.get(app.patient_id) || 'مريض غير مسجل',
        doctor_name: dMap.get(app.doctor_id) || 'طبيب غير محدد'
      })) || [];

      setAppointments(mapped);
    } catch (err: any) {
      console.error("Fetch Error:", err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const filteredAppointments = useMemo(() => {
    return appointments.filter(app => {
      const pName = app.patient_name || '';
      const dName = app.doctor_name || '';
      const s = searchQuery.toLowerCase();
      return pName.toLowerCase().includes(s) || dName.toLowerCase().includes(s);
    });
  }, [appointments, searchQuery]);

  const handleSelectPatient = (id: string, name: string) => {
    setFormData(prev => ({ ...prev, patient_id: id }));
    setSelectedPatientName(name);
    setSearchPatientQuery('');
  };

  const handleAddAppointment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.patient_id || !formData.doctor_id) return alert("يرجى اختيار المريض والطبيب.");

    setIsSubmitting(true);
    try {
      // تحويل الوقت من نظام 12 ساعة إلى 24 ساعة
      let h = parseInt(formData.hour);
      if (formData.period === 'PM' && h < 12) h += 12;
      if (formData.period === 'AM' && h === 12) h = 0;

      const timeStr = `${h.toString().padStart(2, '0')}:${formData.minute}:00`;
      const combinedDate = new Date(`${formData.appointment_date}T${timeStr}`);

      const { error } = await supabase
        .from('appointments')
        .insert([{
          patient_id: formData.patient_id,
          doctor_id: formData.doctor_id,
          appointment_date: combinedDate.toISOString(),
          status: formData.status,
          notes: formData.notes.trim()
        }]);

      if (error) throw error;
      await fetchAppointments();
      setIsModalOpen(false);
      resetForm();
    } catch (err: any) {
      alert("خطأ: " + err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const resetForm = () => {
    setFormData({
      patient_id: '',
      doctor_id: currentUser?.role === UserRole.DOCTOR ? currentUser.id : '',
      appointment_date: new Date().toISOString().split('T')[0],
      hour: '10',
      minute: '00',
      period: 'AM',
      notes: '',
      status: AppointmentStatus.PENDING
    });
    setSelectedPatientName(null);
    setSearchPatientQuery('');
  };

  const updateStatus = async (id: string, newStatus: AppointmentStatus) => {
    try {
      const { error } = await supabase.from('appointments').update({ status: newStatus }).eq('id', id);
      if (!error) fetchAppointments();
    } catch (err: any) {
      console.error(err);
    }
  };

  const filteredPatientList = useMemo(() => {
    if (!searchPatientQuery) return [];
    return patients.filter(p => p.name.toLowerCase().includes(searchPatientQuery.toLowerCase())).slice(0, 5);
  }, [patients, searchPatientQuery]);

  return (
    <div className="space-y-6 text-right animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-800 tracking-tight">جدول المواعيد</h1>
        </div>
        <button 
          onClick={() => { resetForm(); setIsModalOpen(true); }}
          className="bg-indigo-600 text-white px-6 py-3.5 rounded-2xl font-black text-sm shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all flex items-center gap-2 justify-center"
        >
          حجز موعد جديد
        </button>
      </div>

      <div className="bg-white p-4 rounded-3xl border border-slate-100 shadow-xl shadow-slate-200/20 space-y-4">
        <div className="flex flex-wrap items-center gap-3">
           <button onClick={() => setViewMode('TODAY')} className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all border ${viewMode === 'TODAY' ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-400'}`}>اليوم</button>
           <button onClick={() => setViewMode('FUTURE')} className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all border ${viewMode === 'FUTURE' ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-400'}`}>القادمة</button>
           <button onClick={() => setViewMode('ALL')} className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all border ${viewMode === 'ALL' ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-400'}`}>السجل الكامل</button>

           <div className="flex-1 min-w-[200px] relative">
            <input 
              type="text" 
              placeholder="بحث في المواعيد..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-10 py-2.5 text-xs font-black outline-none"
            />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-3">
        {isLoading ? (
          <div className="p-20 text-center flex flex-col items-center gap-4">
            <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
            <p className="text-slate-400 font-black text-sm">جاري تحديث المواعيد...</p>
          </div>
        ) : filteredAppointments.length > 0 ? (
          filteredAppointments.map((app) => (
            <div key={app.id} className="bg-white p-5 rounded-[2rem] border border-slate-50 shadow-sm hover:shadow-md transition-all flex items-center justify-between group">
              <div className="flex items-center gap-5">
                <div className="w-14 h-14 bg-indigo-50 rounded-2xl flex flex-col items-center justify-center border border-indigo-100 group-hover:bg-indigo-600 transition-colors text-center p-1">
                  <span className="text-indigo-600 font-black text-[9px] group-hover:text-white leading-tight">
                    {new Date(app.appointment_date).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit', hour12: true })}
                  </span>
                  <span className="text-indigo-300 font-bold text-[8px] group-hover:text-indigo-100">
                    {new Date(app.appointment_date).toLocaleDateString('ar-EG', { day: '2-digit', month: '2-digit' })}
                  </span>
                </div>
                <div>
                  <h3 className="font-black text-slate-800 text-base">{app.patient_name}</h3>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded-md font-bold">الطبيب: {app.doctor_name}</span>
                    <span className="text-[10px] text-slate-400 font-medium italic">{app.notes}</span>
                  </div>
                </div>
              </div>
              <select 
                value={app.status}
                onChange={(e) => updateStatus(app.id, e.target.value as AppointmentStatus)}
                className={`text-[10px] font-black px-4 py-2 rounded-xl border-none outline-none cursor-pointer ${
                  app.status === AppointmentStatus.PENDING ? 'bg-amber-50 text-amber-600' :
                  app.status === AppointmentStatus.CONFIRMED ? 'bg-indigo-50 text-indigo-600' :
                  app.status === AppointmentStatus.COMPLETED ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'
                }`}
              >
                <option value={AppointmentStatus.PENDING}>انتظار</option>
                <option value={AppointmentStatus.CONFIRMED}>مؤكد</option>
                <option value={AppointmentStatus.COMPLETED}>مكتمل</option>
                <option value={AppointmentStatus.CANCELLED}>ملغى</option>
              </select>
            </div>
          ))
        ) : (
          <div className="p-20 text-center bg-white rounded-[2.5rem] border-2 border-dashed border-slate-100 text-slate-300 italic font-bold">لا توجد مواعيد حالية.</div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] p-8 max-w-md w-full shadow-2xl animate-in zoom-in-95 text-right overflow-y-auto max-h-[90vh]">
            <h2 className="text-2xl font-black text-slate-800 mb-6 border-b border-slate-50 pb-4">حجز موعد جديد</h2>
            <form onSubmit={handleAddAppointment} className="space-y-6">

              {/* المريض */}
              <div>
                <label className="block text-[10px] font-black text-slate-400 mb-2 uppercase tracking-widest mr-1">المريض</label>
                {selectedPatientName ? (
                  <div className="bg-indigo-50 p-4 rounded-2xl flex items-center justify-between border border-indigo-100">
                    <span className="font-black text-indigo-700">{selectedPatientName}</span>
                    <button type="button" onClick={() => { setSelectedPatientName(null); setFormData({...formData, patient_id: ''}); }} className="text-indigo-400 hover:text-indigo-600 font-black">✕</button>
                  </div>
                ) : (
                  <div className="relative">
                    <input 
                      placeholder="ابحث عن مريض..."
                      value={searchPatientQuery}
                      onChange={(e) => setSearchPatientQuery(e.target.value)}
                      className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-4 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                    />
                    {searchPatientQuery && filteredPatientList.length > 0 && (
                      <div className="absolute top-full right-0 left-0 mt-2 bg-white border border-slate-100 rounded-2xl shadow-2xl z-50 overflow-hidden">
                        {filteredPatientList.map(p => (
                          <button key={p.id} type="button" onClick={() => handleSelectPatient(p.id, p.name)} className="w-full p-4 text-right hover:bg-indigo-50 font-black text-sm">
                            {p.name}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* الطبيب */}
              <div>
                <label className="block text-[10px] font-black text-slate-400 mb-2 uppercase tracking-widest mr-1">الطبيب المسؤول</label>
                <select 
                  required
                  value={formData.doctor_id}
                  onChange={(e) => setFormData({...formData, doctor_id: e.target.value})}
                  className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-4 text-sm font-black outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"
                >
                  <option value="">-- اختر الطبيب --</option>
                  {doctors.map(doc => (
                    <option key={doc.id} value={doc.id}>{doc.name}</option>
                  ))}
                </select>
              </div>

              {/* التاريخ مع أيقونة تقويم */}
              <div>
                <label className="block text-[10px] font-black text-slate-400 mb-2 uppercase mr-1 tracking-widest">تاريخ الموعد (التقويم)</label>
                <div className="relative group">
                  <input 
                    type="date" 
                    required 
                    value={formData.appointment_date} 
                    onChange={(e) => setFormData({...formData, appointment_date: e.target.value})} 
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-4 text-sm font-black outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"
                  />
                </div>
              </div>

              {/* الوقت الجديد المقسم */}
              <div>
                <label className="block text-[10px] font-black text-slate-400 mb-2 uppercase mr-1 tracking-widest">توقيت الجلسة</label>
                <div className="grid grid-cols-3 gap-2">
                  <select 
                    value={formData.hour} 
                    onChange={(e) => setFormData({...formData, hour: e.target.value})}
                    className="bg-slate-50 border border-slate-100 rounded-2xl p-3 text-center text-sm font-black outline-none"
                  >
                    {[...Array(12)].map((_, i) => (
                      <option key={i} value={(i + 1).toString().padStart(2, '0')}>{i + 1}</option>
                    ))}
                  </select>
                  <select 
                    value={formData.minute} 
                    onChange={(e) => setFormData({...formData, minute: e.target.value})}
                    className="bg-slate-50 border border-slate-100 rounded-2xl p-3 text-center text-sm font-black outline-none"
                  >
                    {['00', '15', '30', '45'].map(m => (
                      <option key={m} value={m}>{m}</option>
                    ))}
                  </select>
                  <select 
                    value={formData.period} 
                    onChange={(e) => setFormData({...formData, period: e.target.value})}
                    className="bg-indigo-50 border border-indigo-100 text-indigo-700 rounded-2xl p-3 text-center text-sm font-black outline-none"
                  >
                    <option value="AM">AM</option>
                    <option value="PM">PM</option>
                  </select>
                </div>
              </div>

              {/* ملاحظات */}
              <div>
                <label className="block text-[10px] font-black text-slate-400 mb-2 uppercase mr-1 tracking-widest">ملاحظات إضافية</label>
                <textarea 
                  placeholder="سبب الزيارة أو ملاحظة خاصة..."
                  value={formData.notes}
                  onChange={(e) => setFormData({...formData, notes: e.target.value})}
                  className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-4 text-sm font-bold h-24 resize-none outline-none focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div className="pt-4 space-y-3">
                <button 
                  type="submit" 
                  disabled={isSubmitting || !formData.patient_id || !formData.doctor_id}
                  className="w-full bg-indigo-600 text-white py-5 rounded-[1.5rem] font-black text-sm shadow-xl hover:bg-indigo-700 transition-all active:scale-[0.98] disabled:opacity-50"
                >
                  {isSubmitting ? 'جاري المزامنة...' : 'تأكيد وحجز الموعد'}
                </button>
                <button type="button" onClick={() => { setIsModalOpen(false); }} className="w-full text-slate-400 font-black py-2 text-xs">إلغاء العملية</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Appointments;

import React, { useState, useMemo, useEffect } from 'react';
import { Material, MaterialType } from '../types';
import { supabase } from '../services/supabase';

const Inventory: React.FC = () => {
  const [materials, setMaterials] = useState<Material[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [filter, setFilter] = useState<'ALL' | MaterialType>('ALL');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    type: MaterialType.SERVICE,
    selling_price: '',
    cost_price: '',
    stock_quantity: '0',
    order_limit: '10',
    unit: 'قطعة'
  });

  useEffect(() => {
    fetchInventory();
  }, []);

  const fetchInventory = async () => {
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('materials')
        .select('*')
        .order('name', { ascending: true });

      if (error) throw error;
      if (data) setMaterials(data);
    } catch (err: any) {
      console.error("Fetch error:", err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const filteredItems = useMemo(() => {
    return filter === 'ALL' 
      ? materials 
      : materials.filter(item => item.type === filter);
  }, [materials, filter]);

  const handleAddMaterial = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMessage(null);
    setIsSubmitting(true);

    try {
      const costPriceNum = parseFloat(formData.cost_price);
      const sellingPriceNum = parseFloat(formData.selling_price);
      const stockQtyNum = parseInt(formData.stock_quantity);
      const orderLimitNum = parseInt(formData.order_limit);

      const payload: any = {
        name: formData.name.trim(),
        type: formData.type,
        cost_price: isNaN(costPriceNum) ? 0 : costPriceNum,
        unit: formData.type === MaterialType.CONSUMABLE ? formData.unit : 'جلسة',
        stock_quantity: formData.type === MaterialType.CONSUMABLE ? (isNaN(stockQtyNum) ? 0 : stockQtyNum) : 0,
        order_limit: formData.type === MaterialType.CONSUMABLE ? (isNaN(orderLimitNum) ? 10 : orderLimitNum) : 0,
      };

      if (formData.type === MaterialType.SERVICE) {
        payload.selling_price = isNaN(sellingPriceNum) ? 0 : sellingPriceNum;
      } else {
        payload.selling_price = null;
      }

      const { error } = await supabase
        .from('materials')
        .insert([payload]);

      if (error) {
        // إذا كان الخطأ متعلق بـ RLS
        if (error.message.includes('row-level security policy')) {
          throw new Error("خطأ أمان: قاعدة البيانات ترفض الإضافة. يرجى التأكد من تفعيل سياسات الـ RLS لجدول materials في لوحة تحكم Supabase.");
        }
        throw error;
      }

      await fetchInventory();
      setIsAddModalOpen(false);
      setFormData({
        name: '', type: MaterialType.SERVICE, selling_price: '', cost_price: '',
        stock_quantity: '0', order_limit: '10', unit: 'قطعة'
      });
      alert("تمت الإضافة بنجاح");
    } catch (error: any) {
      setErrorMessage(error.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 text-right">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-slate-900 tracking-tight">المخزون والخدمات</h1>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={() => { setIsAddModalOpen(true); setErrorMessage(null); }}
            className="bg-indigo-600 text-white px-8 py-3.5 rounded-2xl text-sm font-black hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 flex items-center gap-2"
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            إضافة عنصر جديد
          </button>
        </div>
      </div>

      <div className="flex gap-6 border-b border-slate-100 overflow-x-auto no-scrollbar">
        {(['ALL', MaterialType.SERVICE, MaterialType.CONSUMABLE] as const).map(f => (
          <button 
            key={f}
            onClick={() => setFilter(f)}
            className={`px-6 py-4 text-sm font-black transition-all border-b-4 -mb-1 whitespace-nowrap ${
              filter === f ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'
            }`}
          >
            {f === 'ALL' ? 'الكل' : f === MaterialType.SERVICE ? 'الخدمات' : 'المستلزمات المستهلكة'}
          </button>
        ))}
      </div>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-2xl shadow-slate-200/50 overflow-hidden">
        {isLoading ? (
          <div className="p-20 flex flex-col items-center justify-center gap-4">
             <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
             <p className="text-slate-400 font-bold">جاري جلب بيانات المخزون...</p>
          </div>
        ) : filteredItems.length > 0 ? (
          <div className="overflow-x-auto">
            <table className="w-full text-right min-w-[800px]">
              <thead className="bg-slate-50/50 border-b border-slate-100">
                <tr>
                  <th className="px-8 py-5 text-[11px] font-black text-slate-400 uppercase tracking-widest">العنصر</th>
                  <th className="px-8 py-5 text-[11px] font-black text-slate-400 uppercase tracking-widest">التصنيف</th>
                  <th className="px-8 py-5 text-[11px] font-black text-slate-400 uppercase tracking-widest text-left">سعر البيع</th>
                  <th className="px-8 py-5 text-[11px] font-black text-slate-400 uppercase tracking-widest text-left">التكلفة</th>
                  <th className="px-8 py-5 text-[11px] font-black text-slate-400 uppercase tracking-widest text-center">المتوفر</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {filteredItems.map(item => (
                  <tr key={item.id} className="hover:bg-indigo-50/30 transition-colors group">
                    <td className="px-8 py-6 font-black text-slate-800">{item.name}</td>
                    <td className="px-8 py-6">
                      <span className={`text-[9px] font-black px-3 py-1 rounded-lg border ${
                        item.type === MaterialType.SERVICE ? 'bg-indigo-50 text-indigo-600 border-indigo-100' : 'bg-amber-50 text-amber-600 border-amber-100'
                      }`}>
                        {item.type === MaterialType.SERVICE ? 'خدمة' : 'مادة مستهلكة'}
                      </span>
                    </td>
                    <td className="px-8 py-6 text-left font-black text-slate-700">
                      {item.selling_price !== null ? `$${item.selling_price}` : '—'}
                    </td>
                    <td className="px-8 py-6 text-left font-black text-slate-400">${item.cost_price}</td>
                    <td className="px-8 py-6 text-center font-black">
                      {item.type === MaterialType.SERVICE ? '—' : `${item.stock_quantity} ${item.unit}`}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="p-20 text-center text-slate-400 font-medium italic">
            لا توجد عناصر لعرضها.
          </div>
        )}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] p-8 max-w-lg w-full shadow-2xl animate-in zoom-in-95 text-right overflow-y-auto max-h-[90vh]">
            <h2 className="text-2xl font-black text-slate-800 mb-6">إضافة عنصر جديد</h2>

            {errorMessage && (
              <div className="mb-6 p-4 bg-rose-50 border border-rose-100 text-rose-600 text-xs font-bold rounded-2xl leading-relaxed">
                <p className="mb-2">⚠️ {errorMessage}</p>
                <p className="text-[10px] text-rose-400">تأكد من تطبيق كود SQL المحدث في لوحة تحكم Supabase.</p>
              </div>
            )}

            <form onSubmit={handleAddMaterial} className="space-y-5">
              <div>
                <label className="block text-xs font-black text-slate-400 mb-1.5 uppercase tracking-widest">الاسم</label>
                <input required value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} className="w-full px-5 py-3.5 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold" />
              </div>

              <div>
                <label className="block text-xs font-black text-slate-400 mb-1.5 uppercase tracking-widest">التصنيف</label>
                <select value={formData.type} onChange={(e) => setFormData({...formData, type: e.target.value as MaterialType})} className="w-full px-5 py-3.5 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold bg-white">
                  <option value={MaterialType.SERVICE}>جلسة / خدمة</option>
                  <option value={MaterialType.CONSUMABLE}>مادة مستهلكة</option>
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <input placeholder="التكلفة" type="number" step="0.01" required value={formData.cost_price} onChange={(e) => setFormData({...formData, cost_price: e.target.value})} className="w-full px-5 py-3.5 rounded-2xl border border-slate-200 font-bold outline-none" />
                <input placeholder="سعر البيع" type="number" step="0.01" disabled={formData.type === MaterialType.CONSUMABLE} required={formData.type === MaterialType.SERVICE} value={formData.selling_price} onChange={(e) => setFormData({...formData, selling_price: e.target.value})} className="w-full px-5 py-3.5 rounded-2xl border border-slate-200 font-bold outline-none disabled:bg-slate-50" />
              </div>

              {formData.type === MaterialType.CONSUMABLE && (
                <div className="grid grid-cols-2 gap-4">
                  <input placeholder="الكمية" type="number" value={formData.stock_quantity} onChange={(e) => setFormData({...formData, stock_quantity: e.target.value})} className="w-full px-5 py-3.5 rounded-2xl border border-slate-200 font-bold outline-none" />
                  <input placeholder="الوحدة (قطعة..)" value={formData.unit} onChange={(e) => setFormData({...formData, unit: e.target.value})} className="w-full px-5 py-3.5 rounded-2xl border border-slate-200 font-bold outline-none" />
                </div>
              )}

              <div className="pt-4 flex flex-col gap-3">
                <button type="submit" disabled={isSubmitting} className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black text-sm hover:bg-indigo-700 shadow-xl disabled:opacity-50">
                  {isSubmitting ? 'جاري الحفظ...' : 'حفظ في السحابة'}
                </button>
                <button type="button" onClick={() => setIsAddModalOpen(false)} className="w-full text-slate-400 font-bold py-2">إلغاء</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect } from 'react';
import { User, UserRole } from '../types';
import { supabase } from '../services/supabase';

const AccountManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showAddModal, setShowAddModal] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [newUser, setNewUser] = useState({ name: '', username: '', role: UserRole.DOCTOR, password: '' });
  const [error, setError] = useState('');

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) setUsers(data);
    } catch (err: any) {
      console.error("Error fetching users:", err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddUser = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const cleanUsername = newUser.username.trim().toLowerCase().replace(/\s/g, '');

    if (!cleanUsername) {
      setError('يرجى إدخال معرف الموظف');
      return;
    }

    if (newUser.password.length < 6) {
      setError('كلمة المرور يجب أن تكون 6 خانات على الأقل');
      return;
    }

    setIsSubmitting(true);
    try {
      // حفظ الموظف في جدول البروفايلات
      const { data, error: profileError } = await supabase
        .from('profiles')
        .insert([{
          username: cleanUsername,
          name: newUser.name.trim(),
          role: newUser.role,
          password_plain: newUser.password
        }])
        .select();

      if (profileError) {
        if (profileError.message.includes('unique_violation')) {
          throw new Error('هذا المعرف (ID) مستخدم بالفعل لموظف آخر.');
        }
        throw profileError;
      }

      // تحديث الواجهة فوراً بجلب البيانات من السحابة
      await fetchUsers();

      setShowAddModal(false);
      setNewUser({ name: '', username: '', role: UserRole.DOCTOR, password: '' });
      alert(`تم تسجيل الموظف ${newUser.name} بنجاح في قاعدة البيانات.`);
    } catch (err: any) {
      setError(err.message || 'فشل في حفظ البيانات السحابية');
    } finally {
      setIsSubmitting(false);
    }
  };

  const deleteUser = async (id: string, username: string) => {
    if (username === 'admin') return alert('لا يمكن حذف حساب المدير الرئيسي');
    if (confirm(`هل أنت متأكد من حذف حساب @${username} نهائياً؟`)) {
      try {
        const { error } = await supabase
          .from('profiles')
          .delete()
          .eq('id', id);

        if (error) throw error;
        setUsers(users.filter(u => u.id !== id));
      } catch (err: any) {
        alert("خطأ في الحذف: " + err.message);
      }
    }
  };

  return (
    <div className="space-y-8 text-right animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-2xl md:text-3xl font-black text-slate-800 tracking-tight">إدارة الكادر الوظيفي</h1>
        </div>
        <button 
          onClick={() => { setError(''); setShowAddModal(true); }}
          className="bg-indigo-600 text-white px-8 py-4 rounded-2xl font-black text-sm hover:bg-indigo-700 shadow-xl shadow-indigo-100 flex items-center gap-2 justify-center transition-all active:scale-95"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z" /></svg>
          تسجيل موظف جديد
        </button>
      </div>

      <div className="bg-white border border-slate-100 rounded-[2.5rem] shadow-2xl shadow-slate-200/40 overflow-hidden">
        {isLoading ? (
          <div className="p-20 flex flex-col items-center justify-center gap-4">
             <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
             <p className="text-slate-400 font-black text-sm">جاري جلب بيانات الكادر...</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-right min-w-[850px]">
              <thead className="bg-slate-50/50 border-b border-slate-100">
                <tr>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">الموظف</th>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">المعرف (ID)</th>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">كلمة المرور</th>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">الصلاحية</th>
                  <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-left">الإجراءات</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {users.map(user => (
                  <tr key={user.id} className="hover:bg-indigo-50/30 transition-colors group">
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-2xl bg-indigo-100 text-indigo-600 flex items-center justify-center font-black text-lg border-2 border-white shadow-sm shrink-0">
                          {user.name.charAt(0)}
                        </div>
                        <div className="min-w-0">
                          <p className="font-black text-slate-800 truncate">{user.name}</p>
                          <p className="text-[10px] text-slate-400 font-bold uppercase">كادر العيادة</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6 text-center">
                      <code className="bg-slate-100 px-3 py-1.5 rounded-lg text-xs font-black text-indigo-600" dir="ltr">
                        @{user.username}
                      </code>
                    </td>
                    <td className="px-8 py-6 text-center">
                      <span className="text-xs font-mono text-slate-400">
                        {(user as any).password_plain || '••••••••'}
                      </span>
                    </td>
                    <td className="px-8 py-6 text-center">
                      <span className={`text-[10px] font-black px-3 py-1 rounded-xl border ${
                        user.role === UserRole.ADMIN ? 'bg-purple-50 text-purple-600 border-purple-100' : 
                        user.role === UserRole.DOCTOR ? 'bg-indigo-50 text-indigo-600 border-indigo-100' : 'bg-orange-50 text-orange-600 border-orange-100'
                      }`}>
                        {user.role === UserRole.ADMIN ? 'مدير عام' : user.role === UserRole.DOCTOR ? 'طبيب' : 'موظف استقبال'}
                      </span>
                    </td>
                    <td className="px-8 py-6 text-left">
                      <button 
                        onClick={() => deleteUser(user.id, user.username)}
                        className="text-slate-300 hover:text-rose-500 p-2 rounded-xl hover:bg-rose-50 transition-all md:opacity-0 group-hover:opacity-100"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[250] flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] p-8 lg:p-10 max-w-md w-full shadow-2xl animate-in zoom-in-95 text-right my-8">
            <h2 className="text-2xl lg:text-3xl font-black text-slate-800 mb-2">إعداد حساب موظف</h2>
            <p className="text-slate-400 text-xs font-bold mb-8">سيتم الحفظ مباشرة في قاعدة بيانات Supabase.</p>

            {error && (
              <div className="mb-6 p-4 bg-rose-50 text-rose-600 rounded-2xl text-[11px] font-black border border-rose-100 flex items-center gap-2 animate-shake">
                <svg className="w-4 h-4 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                {error}
              </div>
            )}

            <form onSubmit={handleAddUser} className="space-y-5">
              <div>
                <label className="block text-[10px] font-black text-slate-400 mb-2 mr-1 uppercase tracking-widest">الاسم الكامل للموظف</label>
                <input 
                  type="text"
                  required
                  placeholder="مثال: د. ياسين علي"
                  value={newUser.name}
                  onChange={(e) => setNewUser({...newUser, name: e.target.value})}
                  className="w-full px-5 py-4 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold bg-slate-50 transition-all placeholder:text-slate-300"
                />
              </div>

              <div>
                <label className="block text-[10px] font-black text-slate-400 mb-2 mr-1 uppercase tracking-widest">المعرف الفريد (ID Login)</label>
                <div className="relative">
                  <input 
                    type="text"
                    required
                    dir="ltr"
                    placeholder="yassin_dent"
                    value={newUser.username}
                    onChange={(e) => setNewUser({...newUser, username: e.target.value})}
                    className="w-full px-5 py-4 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-black tracking-tight bg-slate-50 transition-all placeholder:text-slate-300"
                  />
                  <span className="absolute left-4 top-4 text-slate-300 font-black text-sm">@</span>
                </div>
              </div>

              <div>
                <label className="block text-[10px] font-black text-slate-400 mb-2 mr-1 uppercase tracking-widest">كلمة المرور الافتراضية</label>
                <input 
                  type="password"
                  required
                  placeholder="••••••••"
                  dir="ltr"
                  value={newUser.password}
                  onChange={(e) => setNewUser({...newUser, password: e.target.value})}
                  className="w-full px-5 py-4 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-black bg-slate-50 transition-all placeholder:text-slate-300"
                />
              </div>

              <div>
                <label className="block text-[10px] font-black text-slate-400 mb-2 mr-1 uppercase tracking-widest">مستوى الصلاحية</label>
                <select 
                  value={newUser.role}
                  onChange={(e) => setNewUser({...newUser, role: e.target.value as UserRole})}
                  className="w-full px-5 py-4 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-black bg-slate-50 cursor-pointer transition-all"
                >
                  <option value={UserRole.DOCTOR}>طبيب (صلاحيات طبية)</option>
                  <option value={UserRole.RECEPTIONIST}>استقبال (صلاحيات إدارية)</option>
                  <option value={UserRole.ADMIN}>مدير عام (صلاحيات كاملة)</option>
                </select>
              </div>

              <div className="pt-6 flex flex-col gap-3">
                <button 
                  type="submit"
                  disabled={isSubmitting}
                  className="w-full bg-indigo-600 text-white py-4 lg:py-5 rounded-[1.5rem] font-black text-sm hover:bg-indigo-700 shadow-xl shadow-indigo-100 transition-all active:scale-[0.98] disabled:opacity-50"
                >
                  {isSubmitting ? 'جاري المزامنة السحابية...' : 'حفظ الموظف في السحابة'}
                </button>
                <button 
                  type="button"
                  onClick={() => setShowAddModal(false)}
                  className="w-full text-slate-400 font-black py-2 hover:text-slate-600 transition-colors text-xs"
                >
                  تراجع وإغلاق
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

