    const message = encodeURIComponent("مرحباً مستشفى ابراهيم، أود حجز موعد جديد.");
    window.open(`https://wa.me/${waStats.phone}?text=${message}`, '_blank');
  };

  return (
    <div className="space-y-6 md:space-y-10 animate-in fade-in duration-700 text-right">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 md:gap-6">
        <div className="space-y-1">
          <h1 className="text-2xl md:text-3xl lg:text-4xl font-black text-slate-800 tracking-tight">نظرة عامة على العيادة</h1>
        </div>
        <div className="bg-emerald-50 border border-emerald-100 px-4 py-2 rounded-2xl flex items-center gap-2.5 shadow-sm self-start">
           <span className="relative flex h-2.5 w-2.5">
             <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
             <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-emerald-500"></span>
           </span>
           <span className="text-[10px] font-black text-emerald-800 uppercase tracking-widest">تزامن السحاب نشط</span>
        </div>
      </div>

      {/* WhatsApp Integration Card */}
      <div className="bg-gradient-to-l from-emerald-600 to-emerald-500 rounded-[2.5rem] p-6 lg:p-8 text-white shadow-xl shadow-emerald-100/50 flex flex-col md:flex-row items-center justify-between gap-6 overflow-hidden relative">
        <div className="relative z-10 space-y-4">
          <div className="flex items-center gap-3">
            <ICONS.WhatsApp className="w-8 h-8" />
            <h2 className="text-xl lg:text-2xl font-black">مركز حجز WhatsApp (n8n Active)</h2>
          </div>
          <p className="text-emerald-50 text-sm font-bold opacity-90 max-w-xl">
            نظام الحجز الآلي يعمل الآن. يتم استقبال طلبات المرضى ومعالجتها بواسطة Gemini AI وربطها بجدول المواعيد آلياً.
          </p>
          <div className="flex flex-wrap gap-4">
            <div className="bg-white/20 backdrop-blur-md px-4 py-2 rounded-xl border border-white/20">
              <p className="text-[10px] font-black uppercase opacity-70">طلبات معلقة اليوم</p>
              <p className="text-xl font-black">{waStats.pending}</p>
            </div>
            <button 
              onClick={openWhatsAppLink}
              className="bg-white text-emerald-600 px-6 py-3 rounded-xl font-black text-sm hover:bg-emerald-50 transition-all flex items-center gap-2"
            >
              نسخ رابط الحجز للمرضى
            </button>
          </div>
        </div>
        <div className="hidden md:block absolute -right-10 -bottom-10 opacity-10">
           <ICONS.WhatsApp className="w-64 h-64" />
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6 lg:gap-8">
        {stats.map((stat, i) => (
          <button 
            key={i} 
            onClick={() => onNavigate(stat.target)}
